```python
def two_sum(nums, target):
    nums_sorted = sorted(enumerate(nums), key=lambda x: x[1])
    l, r = 0, len(nums_sorted) - 1
    while l < r:
        s = nums_sorted[l][1] + nums_sorted[r][1]
        if s == target:
            return sorted([nums_sorted[l][0], nums_sorted[r][0]])
        elif s < target:
            l += 1
        else:
            r -= 1
    return []
```

