-- ===== 同步 solutions.comment_count =====
UPDATE `solutions` s SET s.comment_count = (
  SELECT COUNT(*) FROM `solution_comments` sc WHERE sc.solution_id = s.id AND sc.is_deleted = 0
);

-- ===== 验证: 每个用户的评论数 =====
SELECT 'forum' AS src, author_id, COUNT(*) AS cnt FROM `forum_comments` GROUP BY author_id
UNION ALL
SELECT 'solution' AS src, user_id, COUNT(*) AS cnt FROM `solution_comments` GROUP BY user_id ORDER BY src, cnt DESC;
