INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-001-001', 'fpost-001', NULL, 'mod-mike-001', '关于「一次遍历」的表述我想讨论下: 严格来说, 这其实是「边遍历边维护」, 仍然需要遍历整个数组, 关键是查询从 O(n) 降到了 O(1)。', '关于「一次遍历」的表述我想讨论下: 严格来说, 这其实是「边遍历边维护」, 仍然需要遍历整个数组, 关键是查询从 O(n) 降到了 O(1)。', '2026-05-01 10:01:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-002', 'fpost-001', NULL, 'super-root-001', '刚试了一下用 Rust 实现, 所有权 + 借用检查一开始有点别扭, 写熟后其实比 C++ 安全很多。要不要我也发一版?', '刚试了一下用 Rust 实现, 所有权 + 借用检查一开始有点别扭, 写熟后其实比 C++ 安全很多。要不要我也发一版?', '2026-05-01 10:13:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-003', 'fpost-001', NULL, 'user-bob-002', '复杂度分析这块建议补一下: 哈希表的均摊 O(1) 实际上有比较高的常数, 在小数据量下未必比双指针快。', '复杂度分析这块建议补一下: 哈希表的均摊 O(1) 实际上有比较高的常数, 在小数据量下未必比双指针快。', '2026-05-01 10:21:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-004', 'fpost-001', 'fcmt-001-001', 'user-bob-002', '可以参考 `collections.Counter` 或 `defaultdict(int)`, 但这道题用不到计数, 反而拖累性能。', '可以参考 `collections.Counter` 或 `defaultdict(int)`, 但这道题用不到计数, 反而拖累性能。', '2026-05-01 10:09:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-005', 'fpost-001', 'fcmt-001-004', 'mod-mike-001', '**@super_root** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '**@super_root** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '2026-05-01 10:13:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-006', 'fpost-001', 'fcmt-001-001', 'user-carol-003', '**@eva_zhang** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '**@eva_zhang** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '2026-05-01 10:09:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-007', 'fpost-001', 'fcmt-001-006', 'user-david-004', '**@mike_mod** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '**@mike_mod** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '2026-05-01 10:13:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-008', 'fpost-001', 'fcmt-001-002', 'super-vp-002', '**@alice_coder** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '**@alice_coder** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '2026-05-01 10:21:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-009', 'fpost-001', 'fcmt-001-008', 'user-frank-006', '**@admin_two** 那个 `try/except` 模式我之前以为有性能问题, 原来是误解。Python 之父说过: 「EAFP 比 LBYL 更 Pythonic」, 我站 EAFP 阵营。', '**@admin_two** 那个 `try/except` 模式我之前以为有性能问题, 原来是误解。Python 之父说过: 「EAFP 比 LBYL 更 Pythonic」, 我站 EAFP 阵营。', '2026-05-01 10:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-010', 'fpost-001', 'fcmt-001-002', 'admin', '**@bob_dev** 这种边界 case 我都加到单元测试里, 覆盖率 100% 才能 merge。生产代码别偷懒。', '**@bob_dev** 这种边界 case 我都加到单元测试里, 覆盖率 100% 才能 merge。生产代码别偷懒。', '2026-05-01 10:22:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-011', 'fpost-001', 'fcmt-001-010', 'user-alice-001', '**@david_chen** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '**@david_chen** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '2026-05-01 10:25:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-012', 'fpost-001', 'fcmt-001-003', 'user-david-004', '**@frank_lee** 提的 `defaultdict` 思路我试过, 性能反而下降, 因为创建 defaultdict 本身有开销。普通 `dict` + `setdefault` 更轻量。', '**@frank_lee** 提的 `defaultdict` 思路我试过, 性能反而下降, 因为创建 defaultdict 本身有开销。普通 `dict` + `setdefault` 更轻量。', '2026-05-01 10:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-013', 'fpost-001', 'fcmt-001-012', 'mod-nina-002', '**@super_vp** 提的「思维模式」我深有体会, 我现在已经不刷题了, 改成「每天 30 分钟, 复盘一道经典题的 3 种解法」。', '**@super_vp** 提的「思维模式」我深有体会, 我现在已经不刷题了, 改成「每天 30 分钟, 复盘一道经典题的 3 种解法」。', '2026-05-01 10:30:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-014', 'fpost-001', 'fcmt-001-003', 'user-eva-005', '我面试阿里时被追问过「如果内存只有 1MB, n=10^7 怎么办」, 答案是: 外排序 + 归并, 哈希表 OOM 了。这种边界问题才见真功夫。', '我面试阿里时被追问过「如果内存只有 1MB, n=10^7 怎么办」, 答案是: 外排序 + 归并, 哈希表 OOM 了。这种边界问题才见真功夫。', '2026-05-01 10:31:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-015', 'fpost-001', 'fcmt-001-014', 'user-frank-006', '**@admin_two** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '**@admin_two** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '2026-05-01 10:35:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-001-016', 'fpost-001', 'fcmt-001-015', 'user-bob-002', '**@david_chen** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '**@david_chen** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '2026-05-01 10:36:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-002-001', 'fpost-002', NULL, 'admin', '刚试了一下用 Rust 实现, 所有权 + 借用检查一开始有点别扭, 写熟后其实比 C++ 安全很多。要不要我也发一版?', '刚试了一下用 Rust 实现, 所有权 + 借用检查一开始有点别扭, 写熟后其实比 C++ 安全很多。要不要我也发一版?', '2026-05-03 14:33:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-002', 'fpost-002', NULL, 'user-carol-003', '**@david_chen** 提醒的对, 我之前在 LeetCode 评论区看到有人栽在这点上, 输入 `[3,3]` target=6, 只输出一组解。', '**@david_chen** 提醒的对, 我之前在 LeetCode 评论区看到有人栽在这点上, 输入 `[3,3]` target=6, 只输出一组解。', '2026-05-03 14:40:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-003', 'fpost-002', NULL, 'user-frank-006', '实战中如果数组是有序的, 双指针其实更省空间, 不需要额外哈希表。楼主考虑过加一版双指针写法吗?', '实战中如果数组是有序的, 双指针其实更省空间, 不需要额外哈希表。楼主考虑过加一版双指针写法吗?', '2026-05-03 14:46:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-004', 'fpost-002', 'fcmt-002-001', 'mod-nina-002', '**@super_root** 那种写法在数据量大 (n > 10^4) 时, 哈希表查询常数会被乘进去, 排序反而更稳。我做过 benchmark, 临界点大约 n=2000。', '**@super_root** 那种写法在数据量大 (n > 10^4) 时, 哈希表查询常数会被乘进去, 排序反而更稳。我做过 benchmark, 临界点大约 n=2000。', '2026-05-03 14:38:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-005', 'fpost-002', 'fcmt-002-004', 'super-vp-002', '**@bob_dev** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '**@bob_dev** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '2026-05-03 14:43:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-006', 'fpost-002', 'fcmt-002-005', 'user-frank-006', '**@nina_mod** 提的 EAFP 哲学我之前没认真思考过, 谢谢你, 我学到了一课 🙏', '**@nina_mod** 提的 EAFP 哲学我之前没认真思考过, 谢谢你, 我学到了一课 🙏', '2026-05-03 14:44:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-007', 'fpost-002', 'fcmt-002-001', 'admin-002', '**@super_vp** 提到的所有权问题, 我也遇到过。Rust 版推荐用 `HashMap<i32, usize>`, 关键是 value 用 `usize` 而不是 `&i`, 避免借用冲突。', '**@super_vp** 提到的所有权问题, 我也遇到过。Rust 版推荐用 `HashMap<i32, usize>`, 关键是 value 用 `usize` 而不是 `&i`, 避免借用冲突。', '2026-05-03 14:43:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-008', 'fpost-002', 'fcmt-002-007', 'mod-mike-001', '**@super_root** 是的! 我把代码 lint 工具都加上了 `flake8`, 命名 + 风格 + 复杂度一站式检查, 团队效率提升明显。', '**@super_root** 是的! 我把代码 lint 工具都加上了 `flake8`, 命名 + 风格 + 复杂度一站式检查, 团队效率提升明显。', '2026-05-03 14:46:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-009', 'fpost-002', 'fcmt-002-008', 'user-david-004', '**@frank_lee** 提的工具链我马上安排, 团队效率不能再低了。', '**@frank_lee** 提的工具链我马上安排, 团队效率不能再低了。', '2026-05-03 14:49:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-010', 'fpost-002', 'fcmt-002-002', 'user-frank-006', '**@nina_mod** 提到的所有权问题, 我也遇到过。Rust 版推荐用 `HashMap<i32, usize>`, 关键是 value 用 `usize` 而不是 `&i`, 避免借用冲突。', '**@nina_mod** 提到的所有权问题, 我也遇到过。Rust 版推荐用 `HashMap<i32, usize>`, 关键是 value 用 `usize` 而不是 `&i`, 避免借用冲突。', '2026-05-03 14:48:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-011', 'fpost-002', 'fcmt-002-010', 'mod-mike-001', '原来如此, 我之前一直以为 `try` 比 `in` 慢, 反过来了。Python 字典的 `in` 其实是 C 实现的, 怎么会慢呢?', '原来如此, 我之前一直以为 `try` 比 `in` 慢, 反过来了。Python 字典的 `in` 其实是 C 实现的, 怎么会慢呢?', '2026-05-03 14:51:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-012', 'fpost-002', 'fcmt-002-011', 'super-vp-002', '**@alice_coder** 是的, LeetCode 只是入门, 真实工程复杂度 10x 起步。', '**@alice_coder** 是的, LeetCode 只是入门, 真实工程复杂度 10x 起步。', '2026-05-03 14:54:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-013', 'fpost-002', 'fcmt-002-002', 'mod-mike-001', '赞同! 200+ 题之后回头看, 哈希表的核心是「用空间换常数时间」, 这层抽象出来后, 变种题 (如四数之和) 也能秒解。', '赞同! 200+ 题之后回头看, 哈希表的核心是「用空间换常数时间」, 这层抽象出来后, 变种题 (如四数之和) 也能秒解。', '2026-05-03 14:48:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-014', 'fpost-002', 'fcmt-002-013', 'super-root-001', '**@alice_coder** 提的 benchmark 我也想跑一下, 求脚本!', '**@alice_coder** 提的 benchmark 我也想跑一下, 求脚本!', '2026-05-03 14:53:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-015', 'fpost-002', 'fcmt-002-014', 'super-vp-002', '+1, **@admin** 这个建议直接抄到我们项目 README 了 📋', '+1, **@admin** 这个建议直接抄到我们项目 README 了 📋', '2026-05-03 14:54:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-016', 'fpost-002', 'fcmt-002-003', 'mod-nina-002', '对, 「一次遍历」和「边遍历边维护」是同一件事, 表述习惯不同。我个人倾向后者, 更准确。', '对, 「一次遍历」和「边遍历边维护」是同一件事, 表述习惯不同。我个人倾向后者, 更准确。', '2026-05-03 14:54:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-017', 'fpost-002', 'fcmt-002-016', 'user-alice-001', '**@david_chen** 提到的边界 case 我整理了一份 edge case 速查表, 需要的自取。', '**@david_chen** 提到的边界 case 我整理了一份 edge case 速查表, 需要的自取。', '2026-05-03 14:57:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-018', 'fpost-002', 'fcmt-002-003', 'admin-002', '**@super_vp** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '**@super_vp** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '2026-05-03 14:55:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-002-019', 'fpost-002', 'fcmt-002-018', 'user-frank-006', '**@admin_two** 那个浮点 follow-up 我补一版实现: `sum_tolerance = 1e-9`, 比较时 `abs(a + b - target) < sum_tolerance`, 工程常用。', '**@admin_two** 那个浮点 follow-up 我补一版实现: `sum_tolerance = 1e-9`, 比较时 `abs(a + b - target) < sum_tolerance`, 工程常用。', '2026-05-03 14:59:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-003-001', 'fpost-003', NULL, 'user-david-004', '请问楼主, 这道题的 follow-up 如果要求返回所有解 (不只一个) 怎么办? 我的思路是先收集再剪枝, 不知道有没有更优雅的写法。', '请问楼主, 这道题的 follow-up 如果要求返回所有解 (不只一个) 怎么办? 我的思路是先收集再剪枝, 不知道有没有更优雅的写法。', '2026-05-05 09:16:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-002', 'fpost-003', NULL, 'mod-mike-001', '新人提问: 这段代码在 LeetCode 上能过, 但我本地 PyCharm 跑会报 `NameError`, 是不是缺 import?', '新人提问: 这段代码在 LeetCode 上能过, 但我本地 PyCharm 跑会报 `NameError`, 是不是缺 import?', '2026-05-05 09:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-003', 'fpost-003', NULL, 'super-root-001', '对面试官来说, 这套解法能展示的是: 选择数据结构的判断力 + 对常数的敏感度。楼主都说到了。', '对面试官来说, 这套解法能展示的是: 选择数据结构的判断力 + 对常数的敏感度。楼主都说到了。', '2026-05-05 09:36:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-004', 'fpost-003', 'fcmt-003-001', 'super-vp-002', '**@alice_coder** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '**@alice_coder** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '2026-05-05 09:24:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-005', 'fpost-003', 'fcmt-003-004', 'user-frank-006', '**@admin_two** 提到的 `valueByIndexMap` 命名我也喜欢, 我司用 `Map<Num, Idx>` 模式 (类名 = 数据结构 + 泛型), 看起来啰嗦但搜索友好。', '**@admin_two** 提到的 `valueByIndexMap` 命名我也喜欢, 我司用 `Map<Num, Idx>` 模式 (类名 = 数据结构 + 泛型), 看起来啰嗦但搜索友好。', '2026-05-05 09:27:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-006', 'fpost-003', 'fcmt-003-001', 'admin', '对, 「一次遍历」和「边遍历边维护」是同一件事, 表述习惯不同。我个人倾向后者, 更准确。', '对, 「一次遍历」和「边遍历边维护」是同一件事, 表述习惯不同。我个人倾向后者, 更准确。', '2026-05-05 09:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-007', 'fpost-003', 'fcmt-003-006', 'user-david-004', '**@mike_mod** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '**@mike_mod** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '2026-05-05 09:30:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-008', 'fpost-003', 'fcmt-003-007', 'user-frank-006', '**@nina_mod** 分享的资源很赞, 收藏了, 准备组内周会分享 🔥', '**@nina_mod** 分享的资源很赞, 收藏了, 准备组内周会分享 🔥', '2026-05-05 09:33:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-009', 'fpost-003', 'fcmt-003-002', 'mod-nina-002', '浮点数那道题 follow-up 很赞! 我面试被问过 `two sum` + 浮点数, 当时没答好, 成了我的黑历史 😅', '浮点数那道题 follow-up 很赞! 我面试被问过 `two sum` + 浮点数, 当时没答好, 成了我的黑历史 😅', '2026-05-05 09:32:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-010', 'fpost-003', 'fcmt-003-009', 'super-root-001', '**@alice_coder** 这种「空间换时间」的总结非常到位, 我准备直接抄到我的笔记里 📝', '**@alice_coder** 这种「空间换时间」的总结非常到位, 我准备直接抄到我的笔记里 📝', '2026-05-05 09:36:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-011', 'fpost-003', 'fcmt-003-010', 'mod-nina-002', '**@super_root** 是的, LeetCode 只是入门, 真实工程复杂度 10x 起步。', '**@super_root** 是的, LeetCode 只是入门, 真实工程复杂度 10x 起步。', '2026-05-05 09:38:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-012', 'fpost-003', 'fcmt-003-002', 'mod-nina-002', '面试官考的是 trade-off, 不是背代码。如果只说一种解法, 显得经验不足; 把双指针 / 哈希 / 排序三种都说一遍, 加分。', '面试官考的是 trade-off, 不是背代码。如果只说一种解法, 显得经验不足; 把双指针 / 哈希 / 排序三种都说一遍, 加分。', '2026-05-05 09:35:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-013', 'fpost-003', 'fcmt-003-012', 'admin-002', '**@super_vp** 提的 EAFP 哲学我之前也纠结过, 现在的准则是: 「凡是会抛异常就用 try, 不会就用 if」。', '**@super_vp** 提的 EAFP 哲学我之前也纠结过, 现在的准则是: 「凡是会抛异常就用 try, 不会就用 if」。', '2026-05-05 09:40:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-014', 'fpost-003', 'fcmt-003-003', 'admin-002', '**@super_vp** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '**@super_vp** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '2026-05-05 09:43:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-015', 'fpost-003', 'fcmt-003-014', 'super-vp-002', '**@bob_dev** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '**@bob_dev** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '2026-05-05 09:46:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-016', 'fpost-003', 'fcmt-003-003', 'super-vp-002', '实测过, 10^6 数据量, PyPy 比 CPython 快约 30%, 哈希表查询常数差异明显。生产环境建议 CPython + Cython 加速。', '实测过, 10^6 数据量, PyPy 比 CPython 快约 30%, 哈希表查询常数差异明显。生产环境建议 CPython + Cython 加速。', '2026-05-05 09:44:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-003-017', 'fpost-003', 'fcmt-003-016', 'user-bob-002', '原来如此, 我之前一直以为 `try` 比 `in` 慢, 反过来了。Python 字典的 `in` 其实是 C 实现的, 怎么会慢呢?', '原来如此, 我之前一直以为 `try` 比 `in` 慢, 反过来了。Python 字典的 `in` 其实是 C 实现的, 怎么会慢呢?', '2026-05-05 09:47:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-004-001', 'fpost-004', NULL, 'user-david-004', '社区的题解质量真的高! 建议版主把这类带多语言对比的置顶, 方便新人入门。**@eva_zhang** 考虑做个目录?', '社区的题解质量真的高! 建议版主把这类带多语言对比的置顶, 方便新人入门。**@eva_zhang** 考虑做个目录?', '2026-05-07 16:00:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-002', 'fpost-004', NULL, 'mod-mike-001', '新人提问: 这段代码在 LeetCode 上能过, 但我本地 PyCharm 跑会报 `NameError`, 是不是缺 import?', '新人提问: 这段代码在 LeetCode 上能过, 但我本地 PyCharm 跑会报 `NameError`, 是不是缺 import?', '2026-05-07 16:13:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-003', 'fpost-004', NULL, 'super-root-001', '感谢分享! 我用同样的思路刷过, 在某些测试用例上有 bug, 后来发现是哈希表初始容量没设, 扩容耗时明显。设置 initialCapacity 后快了一倍。', '感谢分享! 我用同样的思路刷过, 在某些测试用例上有 bug, 后来发现是哈希表初始容量没设, 扩容耗时明显。设置 initialCapacity 后快了一倍。', '2026-05-07 16:21:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-004', 'fpost-004', 'fcmt-004-001', 'user-alice-001', '面试官考的是 trade-off, 不是背代码。如果只说一种解法, 显得经验不足; 把双指针 / 哈希 / 排序三种都说一遍, 加分。', '面试官考的是 trade-off, 不是背代码。如果只说一种解法, 显得经验不足; 把双指针 / 哈希 / 排序三种都说一遍, 加分。', '2026-05-07 16:06:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-005', 'fpost-004', 'fcmt-004-004', 'user-frank-006', '**@admin_two** 这种「空间换时间」的总结非常到位, 我准备直接抄到我的笔记里 📝', '**@admin_two** 这种「空间换时间」的总结非常到位, 我准备直接抄到我的笔记里 📝', '2026-05-07 16:11:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-006', 'fpost-004', 'fcmt-004-005', 'user-david-004', '+1, **@frank_lee** 这个建议直接抄到我们项目 README 了 📋', '+1, **@frank_lee** 这个建议直接抄到我们项目 README 了 📋', '2026-05-07 16:12:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-007', 'fpost-004', 'fcmt-004-001', 'user-bob-002', '我把这篇加到团队 wiki 的「新人必读」了, **@david_chen** 同意吗?', '我把这篇加到团队 wiki 的「新人必读」了, **@david_chen** 同意吗?', '2026-05-07 16:11:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-008', 'fpost-004', 'fcmt-004-007', 'super-root-001', '**@alice_coder** 同意, 生产代码和 LeetCode 完全两个世界, 我现在养成习惯: 写完先想边界 case。', '**@alice_coder** 同意, 生产代码和 LeetCode 完全两个世界, 我现在养成习惯: 写完先想边界 case。', '2026-05-07 16:16:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-009', 'fpost-004', 'fcmt-004-002', 'admin', '**@bob_dev** 提到的所有权问题, 我也遇到过。Rust 版推荐用 `HashMap<i32, usize>`, 关键是 value 用 `usize` 而不是 `&i`, 避免借用冲突。', '**@bob_dev** 提到的所有权问题, 我也遇到过。Rust 版推荐用 `HashMap<i32, usize>`, 关键是 value 用 `usize` 而不是 `&i`, 避免借用冲突。', '2026-05-07 16:21:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-010', 'fpost-004', 'fcmt-004-009', 'user-alice-001', '**@carol_wu** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '**@carol_wu** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '2026-05-07 16:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-011', 'fpost-004', 'fcmt-004-010', 'user-bob-002', '**@carol_wu** 提的 EAFP 哲学我之前没认真思考过, 谢谢你, 我学到了一课 🙏', '**@carol_wu** 提的 EAFP 哲学我之前没认真思考过, 谢谢你, 我学到了一课 🙏', '2026-05-07 16:27:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-012', 'fpost-004', 'fcmt-004-002', 'user-alice-001', '我把这篇加到团队 wiki 的「新人必读」了, **@carol_wu** 同意吗?', '我把这篇加到团队 wiki 的「新人必读」了, **@carol_wu** 同意吗?', '2026-05-07 16:23:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-013', 'fpost-004', 'fcmt-004-012', 'mod-mike-001', '**@super_root** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '**@super_root** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '2026-05-07 16:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-014', 'fpost-004', 'fcmt-004-013', 'mod-nina-002', '+1, **@super_root** 这个建议直接抄到我们项目 README 了 📋', '+1, **@super_root** 这个建议直接抄到我们项目 README 了 📋', '2026-05-07 16:28:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-015', 'fpost-004', 'fcmt-004-003', 'user-alice-001', '**@carol_wu** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '**@carol_wu** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '2026-05-07 16:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-016', 'fpost-004', 'fcmt-004-015', 'super-root-001', '请问 **@alice_coder** 双指针版那个 `nums_sorted` 排序后, 返回的原始下标怎么对应? 代码里没看到映射, 是不是漏了?', '请问 **@alice_coder** 双指针版那个 `nums_sorted` 排序后, 返回的原始下标怎么对应? 代码里没看到映射, 是不是漏了?', '2026-05-07 16:29:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-017', 'fpost-004', 'fcmt-004-003', 'user-bob-002', '**@david_chen** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '**@david_chen** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '2026-05-07 16:29:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-018', 'fpost-004', 'fcmt-004-017', 'admin', '**@carol_wu** 是的! 我把代码 lint 工具都加上了 `flake8`, 命名 + 风格 + 复杂度一站式检查, 团队效率提升明显。', '**@carol_wu** 是的! 我把代码 lint 工具都加上了 `flake8`, 命名 + 风格 + 复杂度一站式检查, 团队效率提升明显。', '2026-05-07 16:32:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-004-019', 'fpost-004', 'fcmt-004-018', 'user-eva-005', '**@mike_mod** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '**@mike_mod** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '2026-05-07 16:35:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-005-001', 'fpost-005', NULL, 'super-vp-002', '刚试了一下用 Rust 实现, 所有权 + 借用检查一开始有点别扭, 写熟后其实比 C++ 安全很多。要不要我也发一版?', '刚试了一下用 Rust 实现, 所有权 + 借用检查一开始有点别扭, 写熟后其实比 C++ 安全很多。要不要我也发一版?', '2026-05-09 11:05:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-002', 'fpost-005', NULL, 'user-bob-002', '这题的延伸: 如果 target 是浮点数 (例如 1.5 + 2.5 = 4), 哈希表依然有效, 但需要注意浮点比较。', '这题的延伸: 如果 target 是浮点数 (例如 1.5 + 2.5 = 4), 哈希表依然有效, 但需要注意浮点比较。', '2026-05-09 11:11:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-003', 'fpost-005', NULL, 'user-frank-006', '**@frank_lee** 的 Python 实现有个小建议: 变量名 `seen` 容易和 built-in 函数混淆, 在团队规范里我通常要求改成 `value_to_index`。', '**@frank_lee** 的 Python 实现有个小建议: 变量名 `seen` 容易和 built-in 函数混淆, 在团队规范里我通常要求改成 `value_to_index`。', '2026-05-09 11:20:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-004', 'fpost-005', 'fcmt-005-001', 'user-carol-003', '赞同! 200+ 题之后回头看, 哈希表的核心是「用空间换常数时间」, 这层抽象出来后, 变种题 (如四数之和) 也能秒解。', '赞同! 200+ 题之后回头看, 哈希表的核心是「用空间换常数时间」, 这层抽象出来后, 变种题 (如四数之和) 也能秒解。', '2026-05-09 11:12:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-005', 'fpost-005', 'fcmt-005-004', 'user-alice-001', '**@david_chen** 这个 1MB 限制的题, 我之前在分布式系统里遇到过类似的内存约束, 用 LRU cache 是一种思路。', '**@david_chen** 这个 1MB 限制的题, 我之前在分布式系统里遇到过类似的内存约束, 用 LRU cache 是一种思路。', '2026-05-09 11:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-006', 'fpost-005', 'fcmt-005-005', 'mod-mike-001', '**@admin_two** 感谢解答! 我立刻去试一下 💪', '**@admin_two** 感谢解答! 我立刻去试一下 💪', '2026-05-09 11:17:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-007', 'fpost-005', 'fcmt-005-001', 'user-david-004', '对, 「一次遍历」和「边遍历边维护」是同一件事, 表述习惯不同。我个人倾向后者, 更准确。', '对, 「一次遍历」和「边遍历边维护」是同一件事, 表述习惯不同。我个人倾向后者, 更准确。', '2026-05-09 11:13:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-008', 'fpost-005', 'fcmt-005-007', 'admin-002', '**@admin** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '**@admin** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '2026-05-09 11:18:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-009', 'fpost-005', 'fcmt-005-002', 'user-carol-003', '面试时加分项: 主动说出「哈希表最坏 O(n)」、或「Java 8 之后字符串哈希有 DoS 防护」。', '面试时加分项: 主动说出「哈希表最坏 O(n)」、或「Java 8 之后字符串哈希有 DoS 防护」。', '2026-05-09 11:16:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-010', 'fpost-005', 'fcmt-005-009', 'mod-mike-001', '**@super_root** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '**@super_root** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '2026-05-09 11:19:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-011', 'fpost-005', 'fcmt-005-010', 'admin-002', '**@super_vp** 是的, LeetCode 只是入门, 真实工程复杂度 10x 起步。', '**@super_vp** 是的, LeetCode 只是入门, 真实工程复杂度 10x 起步。', '2026-05-09 11:21:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-012', 'fpost-005', 'fcmt-005-002', 'user-david-004', '**@frank_lee** 提醒: `two sum` 算入门第一题, 但变种题 (如 BST 版、矩阵版) 真能区分出候选人水平。建议多练变种。', '**@frank_lee** 提醒: `two sum` 算入门第一题, 但变种题 (如 BST 版、矩阵版) 真能区分出候选人水平。建议多练变种。', '2026-05-09 11:20:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-013', 'fpost-005', 'fcmt-005-012', 'user-bob-002', '**@eva_zhang** 是的! 我把代码 lint 工具都加上了 `flake8`, 命名 + 风格 + 复杂度一站式检查, 团队效率提升明显。', '**@eva_zhang** 是的! 我把代码 lint 工具都加上了 `flake8`, 命名 + 风格 + 复杂度一站式检查, 团队效率提升明显。', '2026-05-09 11:23:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-014', 'fpost-005', 'fcmt-005-003', 'super-root-001', '**@admin** 提的 follow-up 是个好题目! 我写过: 用 `defaultdict(list)` 存所有下标, 遍历时收集结果, 时间 O(n) 空间 O(n)。', '**@admin** 提的 follow-up 是个好题目! 我写过: 用 `defaultdict(list)` 存所有下标, 遍历时收集结果, 时间 O(n) 空间 O(n)。', '2026-05-09 11:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-015', 'fpost-005', 'fcmt-005-014', 'mod-mike-001', '**@super_root** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '**@super_root** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '2026-05-09 11:29:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-016', 'fpost-005', 'fcmt-005-003', 'super-vp-002', '小优化: `target - n` 可以提到循环外计算一次? 不行, 每次的 `n` 不同。所以原写法已经是最优。', '小优化: `target - n` 可以提到循环外计算一次? 不行, 每次的 `n` 不同。所以原写法已经是最优。', '2026-05-09 11:29:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-005-017', 'fpost-005', 'fcmt-005-016', 'user-frank-006', '**@admin_two** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '**@admin_two** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '2026-05-09 11:32:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-006-001', 'fpost-006', NULL, 'super-root-001', '**@super_vp** 提醒的对, 我之前在 LeetCode 评论区看到有人栽在这点上, 输入 `[3,3]` target=6, 只输出一组解。', '**@super_vp** 提醒的对, 我之前在 LeetCode 评论区看到有人栽在这点上, 输入 `[3,3]` target=6, 只输出一组解。', '2026-05-11 13:01:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-002', 'fpost-006', NULL, 'user-alice-001', '收藏了! 准备面试前再过一遍。顺便问下, **@bob_dev** 之前发的《滑动窗口专题》也很有料, 有人整理出合集吗?', '收藏了! 准备面试前再过一遍。顺便问下, **@bob_dev** 之前发的《滑动窗口专题》也很有料, 有人整理出合集吗?', '2026-05-11 13:11:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-003', 'fpost-006', NULL, 'user-david-004', '刚试了一下用 Rust 实现, 所有权 + 借用检查一开始有点别扭, 写熟后其实比 C++ 安全很多。要不要我也发一版?', '刚试了一下用 Rust 实现, 所有权 + 借用检查一开始有点别扭, 写熟后其实比 C++ 安全很多。要不要我也发一版?', '2026-05-11 13:20:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-004', 'fpost-006', 'fcmt-006-001', 'super-vp-002', '**@alice_coder** 提醒: `two sum` 算入门第一题, 但变种题 (如 BST 版、矩阵版) 真能区分出候选人水平。建议多练变种。', '**@alice_coder** 提醒: `two sum` 算入门第一题, 但变种题 (如 BST 版、矩阵版) 真能区分出候选人水平。建议多练变种。', '2026-05-11 13:08:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-005', 'fpost-006', 'fcmt-006-004', 'mod-nina-002', '**@super_vp** 同意, 生产代码和 LeetCode 完全两个世界, 我现在养成习惯: 写完先想边界 case。', '**@super_vp** 同意, 生产代码和 LeetCode 完全两个世界, 我现在养成习惯: 写完先想边界 case。', '2026-05-11 13:13:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-006', 'fpost-006', 'fcmt-006-005', 'user-carol-003', '**@eva_zhang** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '**@eva_zhang** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '2026-05-11 13:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-007', 'fpost-006', 'fcmt-006-001', 'admin', '**@bob_dev** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '**@bob_dev** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '2026-05-11 13:11:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-008', 'fpost-006', 'fcmt-006-007', 'user-carol-003', '**@frank_lee** 这种细节真的是刷题时容易忽略的, 收藏了!', '**@frank_lee** 这种细节真的是刷题时容易忽略的, 收藏了!', '2026-05-11 13:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-009', 'fpost-006', 'fcmt-006-008', 'user-bob-002', '**@david_chen** 说得对! 这次讨论让我对「工程 vs 算法」的差距有了更深的认识。', '**@david_chen** 说得对! 这次讨论让我对「工程 vs 算法」的差距有了更深的认识。', '2026-05-11 13:17:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-010', 'fpost-006', 'fcmt-006-002', 'mod-mike-001', '**@admin_two** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '**@admin_two** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '2026-05-11 13:17:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-011', 'fpost-006', 'fcmt-006-010', 'user-alice-001', '**@david_chen** 提的 benchmark 我也想跑一下, 求脚本!', '**@david_chen** 提的 benchmark 我也想跑一下, 求脚本!', '2026-05-11 13:21:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-012', 'fpost-006', 'fcmt-006-011', 'admin-002', '**@super_vp** 说得对! 这次讨论让我对「工程 vs 算法」的差距有了更深的认识。', '**@super_vp** 说得对! 这次讨论让我对「工程 vs 算法」的差距有了更深的认识。', '2026-05-11 13:22:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-013', 'fpost-006', 'fcmt-006-002', 'mod-nina-002', '浮点数那道题 follow-up 很赞! 我面试被问过 `two sum` + 浮点数, 当时没答好, 成了我的黑历史 😅', '浮点数那道题 follow-up 很赞! 我面试被问过 `two sum` + 浮点数, 当时没答好, 成了我的黑历史 😅', '2026-05-11 13:19:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-014', 'fpost-006', 'fcmt-006-013', 'user-bob-002', '**@eva_zhang** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '**@eva_zhang** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '2026-05-11 13:24:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-015', 'fpost-006', 'fcmt-006-014', 'user-frank-006', '**@nina_mod** 说得对! 这次讨论让我对「工程 vs 算法」的差距有了更深的认识。', '**@nina_mod** 说得对! 这次讨论让我对「工程 vs 算法」的差距有了更深的认识。', '2026-05-11 13:27:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-016', 'fpost-006', 'fcmt-006-003', 'super-vp-002', '浮点数那道题 follow-up 很赞! 我面试被问过 `two sum` + 浮点数, 当时没答好, 成了我的黑历史 😅', '浮点数那道题 follow-up 很赞! 我面试被问过 `two sum` + 浮点数, 当时没答好, 成了我的黑历史 😅', '2026-05-11 13:27:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-017', 'fpost-006', 'fcmt-006-016', 'user-carol-003', '**@frank_lee** 提的「思维模式」我深有体会, 我现在已经不刷题了, 改成「每天 30 分钟, 复盘一道经典题的 3 种解法」。', '**@frank_lee** 提的「思维模式」我深有体会, 我现在已经不刷题了, 改成「每天 30 分钟, 复盘一道经典题的 3 种解法」。', '2026-05-11 13:31:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-018', 'fpost-006', 'fcmt-006-017', 'mod-nina-002', '**@super_root** 提的工具链我马上安排, 团队效率不能再低了。', '**@super_root** 提的工具链我马上安排, 团队效率不能再低了。', '2026-05-11 13:33:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-019', 'fpost-006', 'fcmt-006-003', 'admin', '**@bob_dev** 提的 follow-up 是个好题目! 我写过: 用 `defaultdict(list)` 存所有下标, 遍历时收集结果, 时间 O(n) 空间 O(n)。', '**@bob_dev** 提的 follow-up 是个好题目! 我写过: 用 `defaultdict(list)` 存所有下标, 遍历时收集结果, 时间 O(n) 空间 O(n)。', '2026-05-11 13:31:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-020', 'fpost-006', 'fcmt-006-019', 'user-carol-003', '感谢 **@frank_lee** 的补充! 这层我之前确实没考虑过, 面试大概率会被追问。', '感谢 **@frank_lee** 的补充! 这层我之前确实没考虑过, 面试大概率会被追问。', '2026-05-11 13:34:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-006-021', 'fpost-006', 'fcmt-006-020', 'user-alice-001', '**@carol_wu** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '**@carol_wu** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '2026-05-11 13:35:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-007-001', 'fpost-007', NULL, 'super-vp-002', '社区的题解质量真的高! 建议版主把这类带多语言对比的置顶, 方便新人入门。**@admin** 考虑做个目录?', '社区的题解质量真的高! 建议版主把这类带多语言对比的置顶, 方便新人入门。**@admin** 考虑做个目录?', '2026-05-13 20:01:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-002', 'fpost-007', NULL, 'user-bob-002', '新人提问: 这段代码在 LeetCode 上能过, 但我本地 PyCharm 跑会报 `NameError`, 是不是缺 import?', '新人提问: 这段代码在 LeetCode 上能过, 但我本地 PyCharm 跑会报 `NameError`, 是不是缺 import?', '2026-05-13 20:13:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-003', 'fpost-007', NULL, 'user-eva-005', '感谢分享! 我用同样的思路刷过, 在某些测试用例上有 bug, 后来发现是哈希表初始容量没设, 扩容耗时明显。设置 initialCapacity 后快了一倍。', '感谢分享! 我用同样的思路刷过, 在某些测试用例上有 bug, 后来发现是哈希表初始容量没设, 扩容耗时明显。设置 initialCapacity 后快了一倍。', '2026-05-13 20:19:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-004', 'fpost-007', 'fcmt-007-001', 'super-root-001', '**@admin** 提到的边界我补一下: 空数组时 `for` 循环不执行, 直接 `return []`; 单元素也找不到 pair, 返回空。这是 Python 列表解包自动处理的, Java 则需要显式判断 `nums.length < 2`。', '**@admin** 提到的边界我补一下: 空数组时 `for` 循环不执行, 直接 `return []`; 单元素也找不到 pair, 返回空。这是 Python 列表解包自动处理的, Java 则需要显式判断 `nums.length < 2`。', '2026-05-13 20:07:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-005', 'fpost-007', 'fcmt-007-004', 'user-alice-001', '**@david_chen** 那个 `try/except` 模式我之前以为有性能问题, 原来是误解。Python 之父说过: 「EAFP 比 LBYL 更 Pythonic」, 我站 EAFP 阵营。', '**@david_chen** 那个 `try/except` 模式我之前以为有性能问题, 原来是误解。Python 之父说过: 「EAFP 比 LBYL 更 Pythonic」, 我站 EAFP 阵营。', '2026-05-13 20:12:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-006', 'fpost-007', 'fcmt-007-005', 'mod-nina-002', '**@super_root** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '**@super_root** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '2026-05-13 20:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-007', 'fpost-007', 'fcmt-007-001', 'admin', '**@alice_coder** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '**@alice_coder** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '2026-05-13 20:12:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-008', 'fpost-007', 'fcmt-007-007', 'super-vp-002', '**@bob_dev** 那个 `try/except` 模式我之前以为有性能问题, 原来是误解。Python 之父说过: 「EAFP 比 LBYL 更 Pythonic」, 我站 EAFP 阵营。', '**@bob_dev** 那个 `try/except` 模式我之前以为有性能问题, 原来是误解。Python 之父说过: 「EAFP 比 LBYL 更 Pythonic」, 我站 EAFP 阵营。', '2026-05-13 20:17:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-009', 'fpost-007', 'fcmt-007-002', 'admin-002', '赞同! 200+ 题之后回头看, 哈希表的核心是「用空间换常数时间」, 这层抽象出来后, 变种题 (如四数之和) 也能秒解。', '赞同! 200+ 题之后回头看, 哈希表的核心是「用空间换常数时间」, 这层抽象出来后, 变种题 (如四数之和) 也能秒解。', '2026-05-13 20:20:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-010', 'fpost-007', 'fcmt-007-009', 'mod-mike-001', '**@super_root** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '**@super_root** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '2026-05-13 20:25:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-011', 'fpost-007', 'fcmt-007-002', 'super-root-001', '想问一下 **@admin** 这道题如果输入是链表 (节点值不重复), 还用哈希表吗? 链表版我通常用双指针更优雅。', '想问一下 **@admin** 这道题如果输入是链表 (节点值不重复), 还用哈希表吗? 链表版我通常用双指针更优雅。', '2026-05-13 20:23:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-012', 'fpost-007', 'fcmt-007-011', 'user-alice-001', '**@david_chen** 这种「空间换时间」的总结非常到位, 我准备直接抄到我的笔记里 📝', '**@david_chen** 这种「空间换时间」的总结非常到位, 我准备直接抄到我的笔记里 📝', '2026-05-13 20:28:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-013', 'fpost-007', 'fcmt-007-003', 'super-root-001', '**@admin** 那种写法在数据量大 (n > 10^4) 时, 哈希表查询常数会被乘进去, 排序反而更稳。我做过 benchmark, 临界点大约 n=2000。', '**@admin** 那种写法在数据量大 (n > 10^4) 时, 哈希表查询常数会被乘进去, 排序反而更稳。我做过 benchmark, 临界点大约 n=2000。', '2026-05-13 20:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-014', 'fpost-007', 'fcmt-007-013', 'admin', '**@carol_wu** 提的「思维模式」我深有体会, 我现在已经不刷题了, 改成「每天 30 分钟, 复盘一道经典题的 3 种解法」。', '**@carol_wu** 提的「思维模式」我深有体会, 我现在已经不刷题了, 改成「每天 30 分钟, 复盘一道经典题的 3 种解法」。', '2026-05-13 20:29:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-015', 'fpost-007', 'fcmt-007-003', 'super-vp-002', '小优化: `target - n` 可以提到循环外计算一次? 不行, 每次的 `n` 不同。所以原写法已经是最优。', '小优化: `target - n` 可以提到循环外计算一次? 不行, 每次的 `n` 不同。所以原写法已经是最优。', '2026-05-13 20:30:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-016', 'fpost-007', 'fcmt-007-015', 'user-bob-002', '**@eva_zhang** 提的 `value, ok := m[k]` 我每次都忘, 总是写成 `v := m[k]` 然后 panic。Go 0 值设计有得有失 😅', '**@eva_zhang** 提的 `value, ok := m[k]` 我每次都忘, 总是写成 `v := m[k]` 然后 panic。Go 0 值设计有得有失 😅', '2026-05-13 20:34:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-007-017', 'fpost-007', 'fcmt-007-016', 'user-david-004', '**@frank_lee** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '**@frank_lee** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '2026-05-13 20:37:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-008-001', 'fpost-008', NULL, 'user-carol-003', '感谢分享! 我用同样的思路刷过, 在某些测试用例上有 bug, 后来发现是哈希表初始容量没设, 扩容耗时明显。设置 initialCapacity 后快了一倍。', '感谢分享! 我用同样的思路刷过, 在某些测试用例上有 bug, 后来发现是哈希表初始容量没设, 扩容耗时明显。设置 initialCapacity 后快了一倍。', '2026-05-15 09:00:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-002', 'fpost-008', NULL, 'user-frank-006', '有个细节想确认: `target - n in seen` 这步, 在 Python 里是 O(1) 吗? 字典查找均摊确实是, 但 hash collision 极端情况会退化。', '有个细节想确认: `target - n in seen` 这步, 在 Python 里是 O(1) 吗? 字典查找均摊确实是, 但 hash collision 极端情况会退化。', '2026-05-15 09:10:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-003', 'fpost-008', NULL, 'admin-002', '实战中如果数组是有序的, 双指针其实更省空间, 不需要额外哈希表。楼主考虑过加一版双指针写法吗?', '实战中如果数组是有序的, 双指针其实更省空间, 不需要额外哈希表。楼主考虑过加一版双指针写法吗?', '2026-05-15 09:16:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-004', 'fpost-008', 'fcmt-008-001', 'super-root-001', '**@admin** 提的 `defaultdict` 思路我试过, 性能反而下降, 因为创建 defaultdict 本身有开销。普通 `dict` + `setdefault` 更轻量。', '**@admin** 提的 `defaultdict` 思路我试过, 性能反而下降, 因为创建 defaultdict 本身有开销。普通 `dict` + `setdefault` 更轻量。', '2026-05-15 09:06:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-005', 'fpost-008', 'fcmt-008-004', 'mod-nina-002', '**@super_vp** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '**@super_vp** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '2026-05-15 09:09:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-006', 'fpost-008', 'fcmt-008-001', 'super-vp-002', '**@alice_coder** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '**@alice_coder** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '2026-05-15 09:11:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-007', 'fpost-008', 'fcmt-008-006', 'user-eva-005', '**@nina_mod** 这种「空间换时间」的总结非常到位, 我准备直接抄到我的笔记里 📝', '**@nina_mod** 这种「空间换时间」的总结非常到位, 我准备直接抄到我的笔记里 📝', '2026-05-15 09:14:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-008', 'fpost-008', 'fcmt-008-007', 'mod-mike-001', '**@admin_two** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '**@admin_two** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '2026-05-15 09:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-009', 'fpost-008', 'fcmt-008-002', 'super-vp-002', '实测过, 10^6 数据量, PyPy 比 CPython 快约 30%, 哈希表查询常数差异明显。生产环境建议 CPython + Cython 加速。', '实测过, 10^6 数据量, PyPy 比 CPython 快约 30%, 哈希表查询常数差异明显。生产环境建议 CPython + Cython 加速。', '2026-05-15 09:18:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-010', 'fpost-008', 'fcmt-008-009', 'super-root-001', '**@alice_coder** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '**@alice_coder** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '2026-05-15 09:23:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-011', 'fpost-008', 'fcmt-008-002', 'admin', '**@bob_dev** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '**@bob_dev** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '2026-05-15 09:20:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-012', 'fpost-008', 'fcmt-008-011', 'user-eva-005', '**@nina_mod** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '**@nina_mod** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '2026-05-15 09:24:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-013', 'fpost-008', 'fcmt-008-012', 'mod-mike-001', '**@admin_two** 提的工具链我马上安排, 团队效率不能再低了。', '**@admin_two** 提的工具链我马上安排, 团队效率不能再低了。', '2026-05-15 09:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-014', 'fpost-008', 'fcmt-008-003', 'user-frank-006', '实测过, 10^6 数据量, PyPy 比 CPython 快约 30%, 哈希表查询常数差异明显。生产环境建议 CPython + Cython 加速。', '实测过, 10^6 数据量, PyPy 比 CPython 快约 30%, 哈希表查询常数差异明显。生产环境建议 CPython + Cython 加速。', '2026-05-15 09:21:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-015', 'fpost-008', 'fcmt-008-014', 'admin', '**@carol_wu** 提的链表版 two sum, 我写过递归 + 双指针两种, 递归更短但栈深有风险, 工业界一般用迭代。', '**@carol_wu** 提的链表版 two sum, 我写过递归 + 双指针两种, 递归更短但栈深有风险, 工业界一般用迭代。', '2026-05-15 09:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-016', 'fpost-008', 'fcmt-008-003', 'mod-mike-001', '**@admin_two** 提的 `defaultdict` 思路我试过, 性能反而下降, 因为创建 defaultdict 本身有开销。普通 `dict` + `setdefault` 更轻量。', '**@admin_two** 提的 `defaultdict` 思路我试过, 性能反而下降, 因为创建 defaultdict 本身有开销。普通 `dict` + `setdefault` 更轻量。', '2026-05-15 09:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-008-017', 'fpost-008', 'fcmt-008-016', 'admin', '**@carol_wu** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '**@carol_wu** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '2026-05-15 09:30:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-009-001', 'fpost-009', NULL, 'admin', '实战中如果数组是有序的, 双指针其实更省空间, 不需要额外哈希表。楼主考虑过加一版双指针写法吗?', '实战中如果数组是有序的, 双指针其实更省空间, 不需要额外哈希表。楼主考虑过加一版双指针写法吗?', '2026-05-18 22:03:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-002', 'fpost-009', NULL, 'user-david-004', '思路清晰, 时间复杂度分析到位! 我之前一直用双重循环, 原来一次遍历就能搞定, 学到了 👍', '思路清晰, 时间复杂度分析到位! 我之前一直用双重循环, 原来一次遍历就能搞定, 学到了 👍', '2026-05-18 22:13:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-003', 'fpost-009', NULL, 'user-frank-006', '**@mike_mod** 提醒的对, 我之前在 LeetCode 评论区看到有人栽在这点上, 输入 `[3,3]` target=6, 只输出一组解。', '**@mike_mod** 提醒的对, 我之前在 LeetCode 评论区看到有人栽在这点上, 输入 `[3,3]` target=6, 只输出一组解。', '2026-05-18 22:17:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-004', 'fpost-009', 'fcmt-009-001', 'mod-nina-002', '实测过, 10^6 数据量, PyPy 比 CPython 快约 30%, 哈希表查询常数差异明显。生产环境建议 CPython + Cython 加速。', '实测过, 10^6 数据量, PyPy 比 CPython 快约 30%, 哈希表查询常数差异明显。生产环境建议 CPython + Cython 加速。', '2026-05-18 22:11:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-005', 'fpost-009', 'fcmt-009-004', 'mod-mike-001', '**@super_root** 这个问题我最近面试被问过! 我答「双指针省空间但牺牲时间」, 面试官追问「哪种更优」, 我卡住了。', '**@super_root** 这个问题我最近面试被问过! 我答「双指针省空间但牺牲时间」, 面试官追问「哪种更优」, 我卡住了。', '2026-05-18 22:16:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-006', 'fpost-009', 'fcmt-009-001', 'admin-002', '在 LeetCode 上把 `if target - n in seen` 改成 `try: ... except KeyError: ...` 其实更快, 因为 Python 的 `in` 比 `try` 慢 (不要相信我, 跑 benchmark)。', '在 LeetCode 上把 `if target - n in seen` 改成 `try: ... except KeyError: ...` 其实更快, 因为 Python 的 `in` 比 `try` 慢 (不要相信我, 跑 benchmark)。', '2026-05-18 22:14:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-007', 'fpost-009', 'fcmt-009-006', 'user-frank-006', '**@admin_two** 这个问题我最近面试被问过! 我答「双指针省空间但牺牲时间」, 面试官追问「哪种更优」, 我卡住了。', '**@admin_two** 这个问题我最近面试被问过! 我答「双指针省空间但牺牲时间」, 面试官追问「哪种更优」, 我卡住了。', '2026-05-18 22:19:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-008', 'fpost-009', 'fcmt-009-002', 'mod-nina-002', '面试时加分项: 主动说出「哈希表最坏 O(n)」、或「Java 8 之后字符串哈希有 DoS 防护」。', '面试时加分项: 主动说出「哈希表最坏 O(n)」、或「Java 8 之后字符串哈希有 DoS 防护」。', '2026-05-18 22:19:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-009', 'fpost-009', 'fcmt-009-008', 'user-eva-005', '**@nina_mod** 这个 1MB 限制的题, 我之前在分布式系统里遇到过类似的内存约束, 用 LRU cache 是一种思路。', '**@nina_mod** 这个 1MB 限制的题, 我之前在分布式系统里遇到过类似的内存约束, 用 LRU cache 是一种思路。', '2026-05-18 22:23:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-010', 'fpost-009', 'fcmt-009-002', 'admin-002', '**@super_vp** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '**@super_vp** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '2026-05-18 22:23:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-011', 'fpost-009', 'fcmt-009-010', 'user-eva-005', '**@nina_mod** 提的工具链比写代码重要。`pre-commit` + `black` + `mypy` 是我司 Python 项目标配。', '**@nina_mod** 提的工具链比写代码重要。`pre-commit` + `black` + `mypy` 是我司 Python 项目标配。', '2026-05-18 22:27:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-012', 'fpost-009', 'fcmt-009-011', 'user-bob-002', '+1, **@david_chen** 这个建议直接抄到我们项目 README 了 📋', '+1, **@david_chen** 这个建议直接抄到我们项目 README 了 📋', '2026-05-18 22:30:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-013', 'fpost-009', 'fcmt-009-003', 'super-root-001', '赞同! 200+ 题之后回头看, 哈希表的核心是「用空间换常数时间」, 这层抽象出来后, 变种题 (如四数之和) 也能秒解。', '赞同! 200+ 题之后回头看, 哈希表的核心是「用空间换常数时间」, 这层抽象出来后, 变种题 (如四数之和) 也能秒解。', '2026-05-18 22:23:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-014', 'fpost-009', 'fcmt-009-013', 'user-carol-003', '感谢 **@frank_lee** 的补充! 这层我之前确实没考虑过, 面试大概率会被追问。', '感谢 **@frank_lee** 的补充! 这层我之前确实没考虑过, 面试大概率会被追问。', '2026-05-18 22:27:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-015', 'fpost-009', 'fcmt-009-003', 'super-vp-002', '我把这篇加到团队 wiki 的「新人必读」了, **@alice_coder** 同意吗?', '我把这篇加到团队 wiki 的「新人必读」了, **@alice_coder** 同意吗?', '2026-05-18 22:26:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-009-016', 'fpost-009', 'fcmt-009-015', 'user-frank-006', '**@admin_two** 那个浮点 follow-up 我补一版实现: `sum_tolerance = 1e-9`, 比较时 `abs(a + b - target) < sum_tolerance`, 工程常用。', '**@admin_two** 那个浮点 follow-up 我补一版实现: `sum_tolerance = 1e-9`, 比较时 `abs(a + b - target) < sum_tolerance`, 工程常用。', '2026-05-18 22:30:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-010-001', 'fpost-010', NULL, 'user-carol-003', '新人提问: 这段代码在 LeetCode 上能过, 但我本地 PyCharm 跑会报 `NameError`, 是不是缺 import?', '新人提问: 这段代码在 LeetCode 上能过, 但我本地 PyCharm 跑会报 `NameError`, 是不是缺 import?', '2026-05-20 14:04:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-002', 'fpost-010', NULL, 'user-frank-006', '这题的延伸: 如果 target 是浮点数 (例如 1.5 + 2.5 = 4), 哈希表依然有效, 但需要注意浮点比较。', '这题的延伸: 如果 target 是浮点数 (例如 1.5 + 2.5 = 4), 哈希表依然有效, 但需要注意浮点比较。', '2026-05-20 14:09:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-003', 'fpost-010', NULL, 'admin-002', '这题的延伸: 如果 target 是浮点数 (例如 1.5 + 2.5 = 4), 哈希表依然有效, 但需要注意浮点比较。', '这题的延伸: 如果 target 是浮点数 (例如 1.5 + 2.5 = 4), 哈希表依然有效, 但需要注意浮点比较。', '2026-05-20 14:20:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-004', 'fpost-010', 'fcmt-010-001', 'admin-002', '在 LeetCode 上把 `if target - n in seen` 改成 `try: ... except KeyError: ...` 其实更快, 因为 Python 的 `in` 比 `try` 慢 (不要相信我, 跑 benchmark)。', '在 LeetCode 上把 `if target - n in seen` 改成 `try: ... except KeyError: ...` 其实更快, 因为 Python 的 `in` 比 `try` 慢 (不要相信我, 跑 benchmark)。', '2026-05-20 14:12:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-005', 'fpost-010', 'fcmt-010-004', 'super-root-001', '**@alice_coder** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '**@alice_coder** 说的对, 算法题就是用来训练「思维模式」的, 不是为了 AC。我现在刷题前会先想 3 种解法再写代码。', '2026-05-20 14:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-006', 'fpost-010', 'fcmt-010-005', 'mod-mike-001', '**@admin_two** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '**@admin_two** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '2026-05-20 14:16:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-007', 'fpost-010', 'fcmt-010-001', 'super-root-001', '**@admin** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '**@admin** 提的 Go 写法我也写过, 注意 Go 1.21+ 才有 `maps` 包, 老项目要自己写 `value, ok := m[k]` 判断。', '2026-05-20 14:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-008', 'fpost-010', 'fcmt-010-007', 'user-bob-002', '**@eva_zhang** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '**@eva_zhang** 写的双指针代码我刚跑了一下, 确实下标对应是 `nums_sorted[l][0]` 这个 index, 返回前 sort 一下就对了。', '2026-05-20 14:18:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-009', 'fpost-010', 'fcmt-010-002', 'user-bob-002', '对, 「一次遍历」和「边遍历边维护」是同一件事, 表述习惯不同。我个人倾向后者, 更准确。', '对, 「一次遍历」和「边遍历边维护」是同一件事, 表述习惯不同。我个人倾向后者, 更准确。', '2026-05-20 14:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-010', 'fpost-010', 'fcmt-010-009', 'user-frank-006', '**@admin_two** 提的 EAFP 哲学我之前也纠结过, 现在的准则是: 「凡是会抛异常就用 try, 不会就用 if」。', '**@admin_two** 提的 EAFP 哲学我之前也纠结过, 现在的准则是: 「凡是会抛异常就用 try, 不会就用 if」。', '2026-05-20 14:19:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-011', 'fpost-010', 'fcmt-010-002', 'user-carol-003', '浮点数那道题 follow-up 很赞! 我面试被问过 `two sum` + 浮点数, 当时没答好, 成了我的黑历史 😅', '浮点数那道题 follow-up 很赞! 我面试被问过 `two sum` + 浮点数, 当时没答好, 成了我的黑历史 😅', '2026-05-20 14:20:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-012', 'fpost-010', 'fcmt-010-011', 'user-eva-005', '**@nina_mod** 提的链表版 two sum, 我写过递归 + 双指针两种, 递归更短但栈深有风险, 工业界一般用迭代。', '**@nina_mod** 提的链表版 two sum, 我写过递归 + 双指针两种, 递归更短但栈深有风险, 工业界一般用迭代。', '2026-05-20 14:23:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-013', 'fpost-010', 'fcmt-010-012', 'user-alice-001', '+1, **@carol_wu** 这个建议直接抄到我们项目 README 了 📋', '+1, **@carol_wu** 这个建议直接抄到我们项目 README 了 📋', '2026-05-20 14:25:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-014', 'fpost-010', 'fcmt-010-003', 'super-root-001', '**@super_vp** 那种写法在数据量大 (n > 10^4) 时, 哈希表查询常数会被乘进去, 排序反而更稳。我做过 benchmark, 临界点大约 n=2000。', '**@super_vp** 那种写法在数据量大 (n > 10^4) 时, 哈希表查询常数会被乘进去, 排序反而更稳。我做过 benchmark, 临界点大约 n=2000。', '2026-05-20 14:25:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-015', 'fpost-010', 'fcmt-010-014', 'user-carol-003', '**@frank_lee** 那个浮点 follow-up 我补一版实现: `sum_tolerance = 1e-9`, 比较时 `abs(a + b - target) < sum_tolerance`, 工程常用。', '**@frank_lee** 那个浮点 follow-up 我补一版实现: `sum_tolerance = 1e-9`, 比较时 `abs(a + b - target) < sum_tolerance`, 工程常用。', '2026-05-20 14:29:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-010-016', 'fpost-010', 'fcmt-010-003', 'super-root-001', '**@admin** 提到的双指针写法我贴在下面, 供参考: ⏎  ⏎ ```python ⏎ def two_sum(nums, target): ⏎     nums_sorted = sorted(enumerate(nums), key=lambda x: x[1]) ⏎     l, r = 0, len(nums_sorted) - 1 ⏎     while l < r: ⏎         s = nums_sorted[l][1] + nums_sorted[r][1] ⏎         if s == target: ⏎             return sorted([nums_sorted[l][0], nums_sorted[r][0]]) ⏎         elif s < target: ⏎             l += 1 ⏎         else: ⏎             r -= 1 ⏎     return [] ⏎ ``` ⏎  ⏎ 空间 O(1) 但需排序, 时间 O(n log n)。', '**@admin** 提到的双指针写法我贴在下面, 供参考:
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-011-001', 'fpost-011', NULL, 'mod-nina-002', '对面试官来说, 这套解法能展示的是: 选择数据结构的判断力 + 对常数的敏感度。楼主都说到了。', '对面试官来说, 这套解法能展示的是: 选择数据结构的判断力 + 对常数的敏感度。楼主都说到了。', '2026-05-22 16:00:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-002', 'fpost-011', NULL, 'super-vp-002', '对面试官来说, 这套解法能展示的是: 选择数据结构的判断力 + 对常数的敏感度。楼主都说到了。', '对面试官来说, 这套解法能展示的是: 选择数据结构的判断力 + 对常数的敏感度。楼主都说到了。', '2026-05-22 16:12:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-003', 'fpost-011', NULL, 'user-bob-002', '想问下, **@carol_wu** 提到的边界场景怎么处理? 比如空数组 / 单元素的情况, 代码里没看到显式判断, 是靠语言默认值兜底吗?', '想问下, **@carol_wu** 提到的边界场景怎么处理? 比如空数组 / 单元素的情况, 代码里没看到显式判断, 是靠语言默认值兜底吗?', '2026-05-22 16:20:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-004', 'fpost-011', 'fcmt-011-001', 'user-carol-003', '**@eva_zhang** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '**@eva_zhang** 提到的 `NameError` 大概率是没 `from typing import List`, 新人常见问题。PyCharm 会标黄提示, 注意看 ⚠️', '2026-05-22 16:08:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-005', 'fpost-011', 'fcmt-011-004', 'user-david-004', '**@mike_mod** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '**@mike_mod** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '2026-05-22 16:11:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-006', 'fpost-011', 'fcmt-011-001', 'user-david-004', '面试官考的是 trade-off, 不是背代码。如果只说一种解法, 显得经验不足; 把双指针 / 哈希 / 排序三种都说一遍, 加分。', '面试官考的是 trade-off, 不是背代码。如果只说一种解法, 显得经验不足; 把双指针 / 哈希 / 排序三种都说一遍, 加分。', '2026-05-22 16:09:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-007', 'fpost-011', 'fcmt-011-006', 'user-carol-003', '**@frank_lee** 提的 `defaultdict(list)` 那段代码能再贴一下吗? 我想本地跑一下看结果。', '**@frank_lee** 提的 `defaultdict(list)` 那段代码能再贴一下吗? 我想本地跑一下看结果。', '2026-05-22 16:12:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-008', 'fpost-011', 'fcmt-011-002', 'admin', '**@alice_coder** 提到的边界我补一下: 空数组时 `for` 循环不执行, 直接 `return []`; 单元素也找不到 pair, 返回空。这是 Python 列表解包自动处理的, Java 则需要显式判断 `nums.length < 2`。', '**@alice_coder** 提到的边界我补一下: 空数组时 `for` 循环不执行, 直接 `return []`; 单元素也找不到 pair, 返回空。这是 Python 列表解包自动处理的, Java 则需要显式判断 `nums.length < 2`。', '2026-05-22 16:19:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-009', 'fpost-011', 'fcmt-011-008', 'user-alice-001', '**@david_chen** 同意! 我面试 Google 时, 面试官就因为我说了「如果是链表版我会用双指针」被加分, 反问环节聊得很深。', '**@david_chen** 同意! 我面试 Google 时, 面试官就因为我说了「如果是链表版我会用双指针」被加分, 反问环节聊得很深。', '2026-05-22 16:22:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-010', 'fpost-011', 'fcmt-011-002', 'admin', '**@bob_dev** 那种写法在数据量大 (n > 10^4) 时, 哈希表查询常数会被乘进去, 排序反而更稳。我做过 benchmark, 临界点大约 n=2000。', '**@bob_dev** 那种写法在数据量大 (n > 10^4) 时, 哈希表查询常数会被乘进去, 排序反而更稳。我做过 benchmark, 临界点大约 n=2000。', '2026-05-22 16:22:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-011', 'fpost-011', 'fcmt-011-010', 'super-vp-002', '**@bob_dev** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '**@bob_dev** 这个问题问得好, 我也被问过。答案是: 哈希表查询 O(1) 摊还, 实际是 O(1 + 哈希冲突), 极端构造输入能把它打成 O(n)。', '2026-05-22 16:27:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-012', 'fpost-011', 'fcmt-011-011', 'user-david-004', '**@frank_lee** 说得对! 这次讨论让我对「工程 vs 算法」的差距有了更深的认识。', '**@frank_lee** 说得对! 这次讨论让我对「工程 vs 算法」的差距有了更深的认识。', '2026-05-22 16:29:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-013', 'fpost-011', 'fcmt-011-003', 'user-david-004', '面试时加分项: 主动说出「哈希表最坏 O(n)」、或「Java 8 之后字符串哈希有 DoS 防护」。', '面试时加分项: 主动说出「哈希表最坏 O(n)」、或「Java 8 之后字符串哈希有 DoS 防护」。', '2026-05-22 16:28:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-014', 'fpost-011', 'fcmt-011-013', 'super-vp-002', '原来如此, 我之前一直以为 `try` 比 `in` 慢, 反过来了。Python 字典的 `in` 其实是 C 实现的, 怎么会慢呢?', '原来如此, 我之前一直以为 `try` 比 `in` 慢, 反过来了。Python 字典的 `in` 其实是 C 实现的, 怎么会慢呢?', '2026-05-22 16:32:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-015', 'fpost-011', 'fcmt-011-014', 'mod-nina-002', '**@super_root** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '**@super_root** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '2026-05-22 16:34:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-016', 'fpost-011', 'fcmt-011-003', 'user-eva-005', '我面试阿里时被追问过「如果内存只有 1MB, n=10^7 怎么办」, 答案是: 外排序 + 归并, 哈希表 OOM 了。这种边界问题才见真功夫。', '我面试阿里时被追问过「如果内存只有 1MB, n=10^7 怎么办」, 答案是: 外排序 + 归并, 哈希表 OOM 了。这种边界问题才见真功夫。', '2026-05-22 16:29:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-017', 'fpost-011', 'fcmt-011-016', 'user-frank-006', '**@admin_two** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '**@admin_two** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '2026-05-22 16:34:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-011-018', 'fpost-011', 'fcmt-011-017', 'user-david-004', '**@frank_lee** 这个回答很到位, 直接 mark, 不再展开。', '**@frank_lee** 这个回答很到位, 直接 mark, 不再展开。', '2026-05-22 16:36:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `forum_comments` (`id`, `post_id`, `parent_id`, `author_id`, `body`, `markdown`, `created_at`, `edited_at`, `is_pinned`, `is_locked`, `is_flagged`, `is_deleted`) VALUES
  ('fcmt-012-001', 'fpost-012', NULL, 'user-alice-001', '刷了 200+ 题才真正体会: 哈希表 + 一次遍历是 **思想**, 不是模板。理解之后能套到很多变种题。', '刷了 200+ 题才真正体会: 哈希表 + 一次遍历是 **思想**, 不是模板。理解之后能套到很多变种题。', '2026-05-25 10:02:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-002', 'fpost-012', NULL, 'user-david-004', '思路清晰, 时间复杂度分析到位! 我之前一直用双重循环, 原来一次遍历就能搞定, 学到了 👍', '思路清晰, 时间复杂度分析到位! 我之前一直用双重循环, 原来一次遍历就能搞定, 学到了 👍', '2026-05-25 10:09:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-003', 'fpost-012', NULL, 'mod-mike-001', '实战中如果数组是有序的, 双指针其实更省空间, 不需要额外哈希表。楼主考虑过加一版双指针写法吗?', '实战中如果数组是有序的, 双指针其实更省空间, 不需要额外哈希表。楼主考虑过加一版双指针写法吗?', '2026-05-25 10:17:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-004', 'fpost-012', 'fcmt-012-001', 'user-bob-002', '**@david_chen** 的双指针代码我跑了一下, 在 LeetCode 上时间比哈希表慢 5 倍, 空间确实省了。面试时主动说清 trade-off 很重要。', '**@david_chen** 的双指针代码我跑了一下, 在 LeetCode 上时间比哈希表慢 5 倍, 空间确实省了。面试时主动说清 trade-off 很重要。', '2026-05-25 10:09:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-005', 'fpost-012', 'fcmt-012-004', 'user-frank-006', '感谢 **@admin_two** 的补充! 这层我之前确实没考虑过, 面试大概率会被追问。', '感谢 **@admin_two** 的补充! 这层我之前确实没考虑过, 面试大概率会被追问。', '2026-05-25 10:14:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-006', 'fpost-012', 'fcmt-012-001', 'user-carol-003', '**@eva_zhang** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '**@eva_zhang** 提醒的对, 命名规范在团队里很重要。我司用 `valueByIndexMap` 这种带类型后缀的命名, 见名知意。', '2026-05-25 10:10:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-007', 'fpost-012', 'fcmt-012-006', 'user-david-004', '**@frank_lee** 提到的 `valueByIndexMap` 命名我也喜欢, 我司用 `Map<Num, Idx>` 模式 (类名 = 数据结构 + 泛型), 看起来啰嗦但搜索友好。', '**@frank_lee** 提到的 `valueByIndexMap` 命名我也喜欢, 我司用 `Map<Num, Idx>` 模式 (类名 = 数据结构 + 泛型), 看起来啰嗦但搜索友好。', '2026-05-25 10:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-008', 'fpost-012', 'fcmt-012-007', 'super-root-001', '**@admin** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '**@admin** 提的那个速查表我下载了, 排版超清晰, 谢谢!', '2026-05-25 10:18:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-009', 'fpost-012', 'fcmt-012-002', 'user-alice-001', '面试官考的是 trade-off, 不是背代码。如果只说一种解法, 显得经验不足; 把双指针 / 哈希 / 排序三种都说一遍, 加分。', '面试官考的是 trade-off, 不是背代码。如果只说一种解法, 显得经验不足; 把双指针 / 哈希 / 排序三种都说一遍, 加分。', '2026-05-25 10:15:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-010', 'fpost-012', 'fcmt-012-009', 'mod-mike-001', '请问 **@super_root** 双指针版那个 `nums_sorted` 排序后, 返回的原始下标怎么对应? 代码里没看到映射, 是不是漏了?', '请问 **@super_root** 双指针版那个 `nums_sorted` 排序后, 返回的原始下标怎么对应? 代码里没看到映射, 是不是漏了?', '2026-05-25 10:19:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-011', 'fpost-012', 'fcmt-012-010', 'user-david-004', '**@frank_lee** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '**@frank_lee** 我把这个讨论链整理成了一篇博客, 大家可以去看看 ✍️', '2026-05-25 10:22:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-012', 'fpost-012', 'fcmt-012-002', 'user-bob-002', '**@david_chen** 提的 `defaultdict` 思路我试过, 性能反而下降, 因为创建 defaultdict 本身有开销。普通 `dict` + `setdefault` 更轻量。', '**@david_chen** 提的 `defaultdict` 思路我试过, 性能反而下降, 因为创建 defaultdict 本身有开销。普通 `dict` + `setdefault` 更轻量。', '2026-05-25 10:19:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-013', 'fpost-012', 'fcmt-012-012', 'user-alice-001', '**@david_chen** 这个 1MB 限制的题, 我之前在分布式系统里遇到过类似的内存约束, 用 LRU cache 是一种思路。', '**@david_chen** 这个 1MB 限制的题, 我之前在分布式系统里遇到过类似的内存约束, 用 LRU cache 是一种思路。', '2026-05-25 10:24:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-014', 'fpost-012', 'fcmt-012-003', 'admin', '我把这篇加到团队 wiki 的「新人必读」了, **@bob_dev** 同意吗?', '我把这篇加到团队 wiki 的「新人必读」了, **@bob_dev** 同意吗?', '2026-05-25 10:25:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-015', 'fpost-012', 'fcmt-012-014', 'super-vp-002', '**@bob_dev** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '**@bob_dev** 那个 `entry().or_insert` 模式我之前用过, 写起来确实比 `if k in m` 简洁, 性能也略好。', '2026-05-25 10:29:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-016', 'fpost-012', 'fcmt-012-015', 'admin', '**@alice_coder** 分享的资源很赞, 收藏了, 准备组内周会分享 🔥', '**@alice_coder** 分享的资源很赞, 收藏了, 准备组内周会分享 🔥', '2026-05-25 10:31:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-017', 'fpost-012', 'fcmt-012-003', 'user-alice-001', '**@carol_wu** 提到的所有权问题, 我也遇到过。Rust 版推荐用 `HashMap<i32, usize>`, 关键是 value 用 `usize` 而不是 `&i`, 避免借用冲突。', '**@carol_wu** 提到的所有权问题, 我也遇到过。Rust 版推荐用 `HashMap<i32, usize>`, 关键是 value 用 `usize` 而不是 `&i`, 避免借用冲突。', '2026-05-25 10:27:00.000', NULL, 0, 0, 0, 0),
  ('fcmt-012-018', 'fpost-012', 'fcmt-012-017', 'user-eva-005', '**@nina_mod** 提的 EAFP 哲学我之前也纠结过, 现在的准则是: 「凡是会抛异常就用 try, 不会就用 if」。', '**@nina_mod** 提的 EAFP 哲学我之前也纠结过, 现在的准则是: 「凡是会抛异常就用 try, 不会就用 if」。', '2026-05-25 10:31:00.000', NULL, 0, 0, 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-001-001', 'sol-s-001', NULL, 'super-vp-002', '有一处建议: **@alice_coder** 在 `seen[n] = i` 之后可以加一行 `assert len(seen) == i + 1` 做调试, 方便排查。', '2026-05-02 10:02:00.000', '2026-05-02 10:02:00.000', 0, 0),
  ('scmt-001-002', 'sol-s-001', NULL, 'user-bob-002', '**@alice_coder** 我注意到你用 `if x in seen` 而不是 `try/except`, 这块有什么考量? 之前看有些人推荐 EAFP 风格。', '2026-05-02 10:10:00.000', '2026-05-02 10:10:00.000', 0, 0),
  ('scmt-001-003', 'sol-s-001', NULL, 'user-eva-005', '**@alice_coder** 我注意到你用 `if x in seen` 而不是 `try/except`, 这块有什么考量? 之前看有些人推荐 EAFP 风格。', '2026-05-02 10:16:00.000', '2026-05-02 10:16:00.000', 0, 0),
  ('scmt-001-004', 'sol-s-001', 'scmt-001-001', 'user-frank-006', '**@nina_mod** 介意不介意呢? 开源协议是 MIT 嘛, 注明出处 + 不要商用就 OK。我之前用 **@nina_mod** 的代码也这样, 大家都这么干。', '2026-05-02 10:07:00.000', '2026-05-02 10:07:00.000', 0, 0),
  ('scmt-001-005', 'sol-s-001', 'scmt-001-004', 'user-bob-002', '**@david_chen** 那个 `unordered_map` 默认构造的问题, 我之前没注意, 看来 C++ 还是要多读《Effective C++》。', '2026-05-02 10:10:00.000', '2026-05-02 10:10:00.000', 0, 0),
  ('scmt-001-006', 'sol-s-001', 'scmt-001-005', 'mod-nina-002', '**@super_root** 分享的链接收藏了, 周末细看 🔖', '2026-05-02 10:13:00.000', '2026-05-02 10:13:00.000', 0, 0),
  ('scmt-001-007', 'sol-s-001', 'scmt-001-001', 'mod-mike-001', '**@admin_two** 动态流场景, 我在 Kafka Streams 里见过类似实现, 维护一个时间窗口, 窗口内的元素做匹配, 窗口外的淘汰。本质就是带 TTL 的哈希表。', '2026-05-02 10:09:00.000', '2026-05-02 10:09:00.000', 0, 0),
  ('scmt-001-008', 'sol-s-001', 'scmt-001-007', 'admin', '感谢 **@bob_dev** 这么详细的解答, 真的学到很多 🙏', '2026-05-02 10:13:00.000', '2026-05-02 10:13:00.000', 0, 0),
  ('scmt-001-009', 'sol-s-001', 'scmt-001-002', 'admin-002', '**@super_vp** 介意不介意呢? 开源协议是 MIT 嘛, 注明出处 + 不要商用就 OK。我之前用 **@super_vp** 的代码也这样, 大家都这么干。', '2026-05-02 10:15:00.000', '2026-05-02 10:15:00.000', 0, 0),
  ('scmt-001-010', 'sol-s-001', 'scmt-001-009', 'user-david-004', '**@frank_lee** 提的边界 case 我整理了一份 edge case 速查表, 自取。', '2026-05-02 10:18:00.000', '2026-05-02 10:18:00.000', 0, 0),
  ('scmt-001-011', 'sol-s-001', 'scmt-001-002', 'super-root-001', '**@admin** Code Review 拿到这种评价不容易, **@admin** 写得确实经得起推敲。我在生产代码里也经常用类似模式。', '2026-05-02 10:17:00.000', '2026-05-02 10:17:00.000', 0, 0),
  ('scmt-001-012', 'sol-s-001', 'scmt-001-011', 'admin', '**@bob_dev** 那个 `try/except` 的 fast path 我之前误解了, 「EAFP 比 LBYL 慢」是反过来的, 学习了!', '2026-05-02 10:21:00.000', '2026-05-02 10:21:00.000', 0, 0),
  ('scmt-001-013', 'sol-s-001', 'scmt-001-012', 'super-root-001', '**@admin** 提的 EAFP vs LBYL 我之前也纠结过, 现在的准则是「异常罕见就 try, 异常常见就 if」。', '2026-05-02 10:22:00.000', '2026-05-02 10:22:00.000', 0, 0),
  ('scmt-001-014', 'sol-s-001', 'scmt-001-003', 'user-alice-001', '**@carol_wu** 那个 follow-up, 改成 `defaultdict(list)` 收集所有下标就行: ⏎  ⏎ ```python ⏎ from collections import defaultdict ⏎  ⏎ def twoSumAll(nums, target): ⏎     pos = defaultdict(list) ⏎     res = [] ⏎     for i, n in enumerate(nums): ⏎         if target - n in pos: ⏎             for j in pos[target - n]: ⏎                 res.append([j, i]) ⏎         pos[n].append(i) ⏎     return res ⏎ ``` ⏎  ⏎ 空间 O(n), 时间 O(n)。', '2026-05-02 10:23:00.000', '2026-05-02 10:23:00.000', 0, 0),
  ('scmt-001-015', 'sol-s-001', 'scmt-001-014', 'user-david-004', '**@frank_lee** 那个「反问」环节我也被问过, 当时答得不好, 现在想想应该反问一下面试官的 follow-up 思路。', '2026-05-02 10:28:00.000', '2026-05-02 10:28:00.000', 0, 0),
  ('scmt-001-016', 'sol-s-001', 'scmt-001-003', 'user-bob-002', '**@david_chen** 复现是好事, 建议加单元测试! 我自己写 C++ 的时候都用 `gtest`, Python 用 `pytest`, 边界 case 覆盖率上 100%。', '2026-05-02 10:25:00.000', '2026-05-02 10:25:00.000', 0, 0),
  ('scmt-001-017', 'sol-s-001', 'scmt-001-016', 'user-carol-003', '**@eva_zhang** 那个「算法相通」的洞察很重要, 我之前学「单调栈」时, 突然想起 two sum 的「边遍历边维护」, 触类旁通!', '2026-05-02 10:30:00.000', '2026-05-02 10:30:00.000', 0, 0),
  ('scmt-001-018', 'sol-s-001', 'scmt-001-017', 'mod-nina-002', '**@super_root** 那个 LeetCode 146 我也练过, 哈希表 + 双向链表是核心, 推荐!', '2026-05-02 10:33:00.000', '2026-05-02 10:33:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-002-001', 'sol-s-002', NULL, 'super-root-001', '**@bob_dev** 写得太好, 已经推荐给学弟学妹了。我们学校 ACM 队训练就用这套模板。', '2026-05-04 11:02:00.000', '2026-05-04 11:02:00.000', 0, 0),
  ('scmt-002-002', 'sol-s-002', NULL, 'user-alice-001', '有一个 follow-up: 如果数组是动态的 (持续流入新元素 + 实时查询 target), 这种解法还成立吗?', '2026-05-04 11:10:00.000', '2026-05-04 11:10:00.000', 0, 0),
  ('scmt-002-003', 'sol-s-002', NULL, 'user-david-004', '时间复杂度 O(n) 很对, 但实测在 n=10^4 时, 双指针反而比哈希表快, 是因为常数问题吗?', '2026-05-04 11:18:00.000', '2026-05-04 11:18:00.000', 0, 0),
  ('scmt-002-004', 'sol-s-002', 'scmt-002-001', 'user-alice-001', '**@carol_wu** 介意不介意呢? 开源协议是 MIT 嘛, 注明出处 + 不要商用就 OK。我之前用 **@carol_wu** 的代码也这样, 大家都这么干。', '2026-05-04 11:09:00.000', '2026-05-04 11:09:00.000', 0, 0),
  ('scmt-002-005', 'sol-s-002', 'scmt-002-004', 'user-frank-006', '**@nina_mod** 是的, 「反复刷」比「刷更多题」更有效, 我现在改成一周只刷 5 道, 但每道刷 3 遍。', '2026-05-04 11:12:00.000', '2026-05-04 11:12:00.000', 0, 0),
  ('scmt-002-006', 'sol-s-002', 'scmt-002-001', 'user-bob-002', '**@david_chen** 不行, **@david_chen** 的解法本质就是「用哈希表换 O(1) 查询」, 不用哈希表就只能双重循环 O(n²) 或排序+双指针 O(n log n)。空间 O(1) + 时间 O(n) 是下界。', '2026-05-04 11:10:00.000', '2026-05-04 11:10:00.000', 0, 0),
  ('scmt-002-007', 'sol-s-002', 'scmt-002-006', 'admin', '**@bob_dev** 那个 `unordered_map` 默认构造的问题, 我之前没注意, 看来 C++ 还是要多读《Effective C++》。', '2026-05-04 11:15:00.000', '2026-05-04 11:15:00.000', 0, 0),
  ('scmt-002-008', 'sol-s-002', 'scmt-002-002', 'admin', '**@bob_dev** 这种「动态流」版本, 其实更接近工业场景: 维护一个固定大小的窗口, 老的滑出, 新的滑入。可以看 `collections.OrderedDict` 或 LRU cache。', '2026-05-04 11:16:00.000', '2026-05-04 11:16:00.000', 0, 0),
  ('scmt-002-009', 'sol-s-002', 'scmt-002-008', 'user-bob-002', '**@david_chen** 那种博客我也写过, 推荐 Hugo + GitHub Pages, 部署简单, 速度也快。', '2026-05-04 11:19:00.000', '2026-05-04 11:19:00.000', 0, 0),
  ('scmt-002-010', 'sol-s-002', 'scmt-002-009', 'user-frank-006', '**@nina_mod** 提的 `__missing__` 细节, 我之前没注意, 看来要重读 Python data model。', '2026-05-04 11:22:00.000', '2026-05-04 11:22:00.000', 0, 0),
  ('scmt-002-011', 'sol-s-002', 'scmt-002-002', 'user-bob-002', '**@carol_wu** 写完博客记得加个 `README.md` 和 `LICENSE`, 顺便开 GitHub Pages, 给自己简历加分。', '2026-05-04 11:20:00.000', '2026-05-04 11:20:00.000', 0, 0),
  ('scmt-002-012', 'sol-s-002', 'scmt-002-011', 'user-eva-005', '**@mike_mod** 那个 `__missing__` 的细节, 我之前不知道, 受教了! 看来还是要多读 Python 文档。', '2026-05-04 11:25:00.000', '2026-05-04 11:25:00.000', 0, 0),
  ('scmt-002-013', 'sol-s-002', 'scmt-002-003', 'user-frank-006', '**@nina_mod** 动态流场景, 我在 Kafka Streams 里见过类似实现, 维护一个时间窗口, 窗口内的元素做匹配, 窗口外的淘汰。本质就是带 TTL 的哈希表。', '2026-05-04 11:23:00.000', '2026-05-04 11:23:00.000', 0, 0),
  ('scmt-002-014', 'sol-s-002', 'scmt-002-013', 'mod-mike-001', '**@nina_mod** 那个「算法相通」的洞察很重要, 我之前学「单调栈」时, 突然想起 two sum 的「边遍历边维护」, 触类旁通!', '2026-05-04 11:26:00.000', '2026-05-04 11:26:00.000', 0, 0),
  ('scmt-002-015', 'sol-s-002', 'scmt-002-003', 'mod-mike-001', '**@admin_two** 那个 C++ 版我看了, `auto seen = unordered_map<int, int>{}` 初始化比 `unordered_map<int, int> seen` 更安全, 避免默认构造的 nullptr deref。', '2026-05-04 11:28:00.000', '2026-05-04 11:28:00.000', 0, 0),
  ('scmt-002-016', 'sol-s-002', 'scmt-002-015', 'user-alice-001', '**@carol_wu** 那个 `__missing__` 性能问题我之前也测过, 默认 `dict.__missing__` 是 pass, 但 `defaultdict` 重写了, 所以有开销。', '2026-05-04 11:31:00.000', '2026-05-04 11:31:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-003-001', 'sol-s-003', NULL, 'user-bob-002', '**@carol_wu** 我注意到你用 `if x in seen` 而不是 `try/except`, 这块有什么考量? 之前看有些人推荐 EAFP 风格。', '2026-05-06 09:03:00.000', '2026-05-06 09:03:00.000', 0, 0),
  ('scmt-003-002', 'sol-s-003', NULL, 'user-eva-005', '性能细节: 在 PyPy 3.9 下跑了 100 万次, 平均 0.7ms, 内存峰值 16MB。**@carol_wu** 的解法稳如老狗 🐕', '2026-05-06 09:07:00.000', '2026-05-06 09:07:00.000', 0, 0),
  ('scmt-003-003', 'sol-s-003', NULL, 'mod-nina-002', '我之前一直用 list.index() 实现, 看了你的题解才明白 list.index() 是 O(n), 难怪大数据量卡死。', '2026-05-06 09:16:00.000', '2026-05-06 09:16:00.000', 0, 0),
  ('scmt-003-004', 'sol-s-003', 'scmt-003-001', 'admin', '**@bob_dev** 那个 PyPy benchmark 我也跑了, 结论一致。这种「快」主要来自 PyPy 的 JIT, 不是 Python 本身的。生产建议 CPython + 关键路径用 Cython。', '2026-05-06 09:08:00.000', '2026-05-06 09:08:00.000', 0, 0),
  ('scmt-003-005', 'sol-s-003', 'scmt-003-004', 'user-bob-002', '**@david_chen** 提的细节我立刻加到自己的代码里!', '2026-05-06 09:12:00.000', '2026-05-06 09:12:00.000', 0, 0),
  ('scmt-003-006', 'sol-s-003', 'scmt-003-001', 'user-alice-001', '**@carol_wu** 会的, **@carol_wu** 题解系列我每周都在追, 上次那个「最长回文子串」的中心扩展法也很经典。', '2026-05-06 09:12:00.000', '2026-05-06 09:12:00.000', 0, 0),
  ('scmt-003-007', 'sol-s-003', 'scmt-003-006', 'user-eva-005', '**@mike_mod** 提的 LeetCode 146 我也刷过, 重点是 `get` 和 `put` 的 O(1) 实现, 双链表 + 哈希表是核心。', '2026-05-06 09:15:00.000', '2026-05-06 09:15:00.000', 0, 0),
  ('scmt-003-008', 'sol-s-003', 'scmt-003-002', 'user-david-004', '**@frank_lee** 会的, **@frank_lee** 题解系列我每周都在追, 上次那个「最长回文子串」的中心扩展法也很经典。', '2026-05-06 09:13:00.000', '2026-05-06 09:13:00.000', 0, 0),
  ('scmt-003-009', 'sol-s-003', 'scmt-003-008', 'super-vp-002', '**@alice_coder** 提的 LeetCode 146 我也刷过, 重点是 `get` 和 `put` 的 O(1) 实现, 双链表 + 哈希表是核心。', '2026-05-06 09:17:00.000', '2026-05-06 09:17:00.000', 0, 0),
  ('scmt-003-010', 'sol-s-003', 'scmt-003-009', 'user-bob-002', '**@david_chen** 提的工具我马上用起来!', '2026-05-06 09:20:00.000', '2026-05-06 09:20:00.000', 0, 0),
  ('scmt-003-011', 'sol-s-003', 'scmt-003-002', 'user-frank-006', '**@mike_mod** 那个「动态流」的题其实更接近 LRU cache, 可以看 LeetCode 146。思路类似, 只是窗口大小固定。', '2026-05-06 09:17:00.000', '2026-05-06 09:17:00.000', 0, 0),
  ('scmt-003-012', 'sol-s-003', 'scmt-003-011', 'user-david-004', '**@frank_lee** 那个时间窗口的工业实现我之前在 Druid 里见过, 内部就是用 LRU + TTL 哈希表做的。', '2026-05-06 09:22:00.000', '2026-05-06 09:22:00.000', 0, 0),
  ('scmt-003-013', 'sol-s-003', 'scmt-003-012', 'admin', '**@bob_dev** 提的工具我马上用起来!', '2026-05-06 09:25:00.000', '2026-05-06 09:25:00.000', 0, 0),
  ('scmt-003-014', 'sol-s-003', 'scmt-003-003', 'super-vp-002', '**@alice_coder** 写博客分享是好事! 写完后可以把链接发到「题解分享」频道, 我帮你转发。', '2026-05-06 09:23:00.000', '2026-05-06 09:23:00.000', 0, 0),
  ('scmt-003-015', 'sol-s-003', 'scmt-003-014', 'user-frank-006', '**@nina_mod** 那个 `try/except` 的 fast path 我之前误解了, 「EAFP 比 LBYL 慢」是反过来的, 学习了!', '2026-05-06 09:28:00.000', '2026-05-06 09:28:00.000', 0, 0),
  ('scmt-003-016', 'sol-s-003', 'scmt-003-015', 'admin-002', '**@super_vp** 这次讨论真的刷新了我对 two sum 的认识, 不只是题, 是背后的 pattern 🎓', '2026-05-06 09:29:00.000', '2026-05-06 09:29:00.000', 0, 0),
  ('scmt-003-017', 'sol-s-003', 'scmt-003-003', 'admin', '**@bob_dev** Code Review 拿到这种评价不容易, **@bob_dev** 写得确实经得起推敲。我在生产代码里也经常用类似模式。', '2026-05-06 09:26:00.000', '2026-05-06 09:26:00.000', 0, 0),
  ('scmt-003-018', 'sol-s-003', 'scmt-003-017', 'user-carol-003', '**@eva_zhang** 那个 `try/except` 的 fast path 我之前误解了, 「EAFP 比 LBYL 慢」是反过来的, 学习了!', '2026-05-06 09:29:00.000', '2026-05-06 09:29:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-004-001', 'sol-s-004', NULL, 'user-carol-003', '**@david_chen** 这题解太赞了! 一遍哈希表确实是最优解, 思路清晰, 代码也简洁。我之前一直双重循环, 学到了!', '2026-05-08 15:00:00.000', '2026-05-08 15:00:00.000', 0, 0),
  ('scmt-004-002', 'sol-s-004', NULL, 'user-frank-006', '面试题, 必须掌握! **@david_chen** 写得真的清晰, 比官方题解好懂 10 倍。', '2026-05-08 15:10:00.000', '2026-05-08 15:10:00.000', 0, 0),
  ('scmt-004-003', 'sol-s-004', NULL, 'admin-002', '请教一下, **@david_chen** 在 `target - n in seen` 这一步, 如果数组里有负数会出问题吗? 我测了几个 case, 好像不会, 但原理上不太确定。', '2026-05-08 15:16:00.000', '2026-05-08 15:16:00.000', 0, 0),
  ('scmt-004-004', 'sol-s-004', 'scmt-004-001', 'super-vp-002', '**@alice_coder** 负数 target 也一样, 哈希表只关心 key 是不是存在, 不关心 value 是什么。放心用。', '2026-05-08 15:05:00.000', '2026-05-08 15:05:00.000', 0, 0),
  ('scmt-004-005', 'sol-s-004', 'scmt-004-004', 'admin-002', '**@super_vp** 那个 `__missing__` 性能问题我之前也测过, 默认 `dict.__missing__` 是 pass, 但 `defaultdict` 重写了, 所以有开销。', '2026-05-08 15:10:00.000', '2026-05-08 15:10:00.000', 0, 0),
  ('scmt-004-006', 'sol-s-004', 'scmt-004-005', 'user-frank-006', '**@nina_mod** 提的 `__missing__` 细节, 我之前没注意, 看来要重读 Python data model。', '2026-05-08 15:12:00.000', '2026-05-08 15:12:00.000', 0, 0),
  ('scmt-004-007', 'sol-s-004', 'scmt-004-001', 'admin', '**@bob_dev** 负数 target 也一样, 哈希表只关心 key 是不是存在, 不关心 value 是什么。放心用。', '2026-05-08 15:09:00.000', '2026-05-08 15:09:00.000', 0, 0),
  ('scmt-004-008', 'sol-s-004', 'scmt-004-007', 'admin-002', '**@super_vp** 提的边界 case 我整理了一份 edge case 速查表, 自取。', '2026-05-08 15:13:00.000', '2026-05-08 15:13:00.000', 0, 0),
  ('scmt-004-009', 'sol-s-004', 'scmt-004-008', 'user-eva-005', '**@mike_mod** 提的 EAFP vs LBYL 我之前也纠结过, 现在的准则是「异常罕见就 try, 异常常见就 if」。', '2026-05-08 15:15:00.000', '2026-05-08 15:15:00.000', 0, 0),
  ('scmt-004-010', 'sol-s-004', 'scmt-004-002', 'super-root-001', '**@admin** 那个 C++ 版我看了, `auto seen = unordered_map<int, int>{}` 初始化比 `unordered_map<int, int> seen` 更安全, 避免默认构造的 nullptr deref。', '2026-05-08 15:14:00.000', '2026-05-08 15:14:00.000', 0, 0),
  ('scmt-004-011', 'sol-s-004', 'scmt-004-010', 'user-eva-005', '**@mike_mod** 这个 `defaultdict` 的代码我收藏了, 等下就测一下 ✨', '2026-05-08 15:19:00.000', '2026-05-08 15:19:00.000', 0, 0),
  ('scmt-004-012', 'sol-s-004', 'scmt-004-011', 'user-frank-006', '**@nina_mod** 提的 EAFP vs LBYL 我之前也纠结过, 现在的准则是「异常罕见就 try, 异常常见就 if」。', '2026-05-08 15:22:00.000', '2026-05-08 15:22:00.000', 0, 0),
  ('scmt-004-013', 'sol-s-004', 'scmt-004-002', 'super-vp-002', '**@alice_coder** 那个 PyPy benchmark 我也跑了, 结论一致。这种「快」主要来自 PyPy 的 JIT, 不是 Python 本身的。生产建议 CPython + 关键路径用 Cython。', '2026-05-08 15:18:00.000', '2026-05-08 15:18:00.000', 0, 0),
  ('scmt-004-014', 'sol-s-004', 'scmt-004-013', 'mod-mike-001', '**@admin_two** 那种博客我也写过, 推荐 Hugo + GitHub Pages, 部署简单, 速度也快。', '2026-05-08 15:21:00.000', '2026-05-08 15:21:00.000', 0, 0),
  ('scmt-004-015', 'sol-s-004', 'scmt-004-014', 'mod-nina-002', '**@super_root** 同意! 反复回看经典题, 比刷新题效率高 10 倍 📈', '2026-05-08 15:23:00.000', '2026-05-08 15:23:00.000', 0, 0),
  ('scmt-004-016', 'sol-s-004', 'scmt-004-003', 'user-frank-006', '**@nina_mod** 那个 `try/except KeyError` 我之前用错场景了, Python EAFP 在「异常罕见」的场景下最优, 这道题里 `target - n` 大概率不在, 所以适合 try。', '2026-05-08 15:23:00.000', '2026-05-08 15:23:00.000', 0, 0),
  ('scmt-004-017', 'sol-s-004', 'scmt-004-016', 'super-vp-002', '**@alice_coder** 完美的回复! 负数场景困扰我很久, 终于搞明白了 🎉', '2026-05-08 15:26:00.000', '2026-05-08 15:26:00.000', 0, 0),
  ('scmt-004-018', 'sol-s-004', 'scmt-004-003', 'mod-mike-001', '**@admin_two** 动态流场景, 我在 Kafka Streams 里见过类似实现, 维护一个时间窗口, 窗口内的元素做匹配, 窗口外的淘汰。本质就是带 TTL 的哈希表。', '2026-05-08 15:26:00.000', '2026-05-08 15:26:00.000', 0, 0),
  ('scmt-004-019', 'sol-s-004', 'scmt-004-018', 'admin-002', '**@super_vp** 的回复每次都这么专业, **@super_vp** 这种「教科书」题解的评论区就该这么高质量 💯', '2026-05-08 15:31:00.000', '2026-05-08 15:31:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-005-001', 'sol-s-005', NULL, 'mod-nina-002', '时间复杂度 O(n) 很对, 但实测在 n=10^4 时, 双指针反而比哈希表快, 是因为常数问题吗?', '2026-05-10 10:02:00.000', '2026-05-10 10:02:00.000', 0, 0),
  ('scmt-005-002', 'sol-s-005', NULL, 'super-vp-002', '**@eva_zhang** 在 Reddit 上看到有人说这解法「too simple」, 但 LeetCode 评论区里讨论得最多的还是这版。新人就该学这种。', '2026-05-10 10:07:00.000', '2026-05-10 10:07:00.000', 0, 0),
  ('scmt-005-003', 'sol-s-005', NULL, 'user-bob-002', '**@eva_zhang** 我注意到你用 `if x in seen` 而不是 `try/except`, 这块有什么考量? 之前看有些人推荐 EAFP 风格。', '2026-05-10 10:15:00.000', '2026-05-10 10:15:00.000', 0, 0),
  ('scmt-005-004', 'sol-s-005', 'scmt-005-001', 'super-root-001', '**@admin** 那个 `assert` 调试思路好, 我学到了! 我一般用 `print`, 看来该升级一下工具链了。', '2026-05-10 10:07:00.000', '2026-05-10 10:07:00.000', 0, 0),
  ('scmt-005-005', 'sol-s-005', 'scmt-005-004', 'user-eva-005', '**@mike_mod** 那个「算法相通」的洞察很重要, 我之前学「单调栈」时, 突然想起 two sum 的「边遍历边维护」, 触类旁通!', '2026-05-10 10:11:00.000', '2026-05-10 10:11:00.000', 0, 0),
  ('scmt-005-006', 'sol-s-005', 'scmt-005-005', 'user-carol-003', '感谢 **@eva_zhang** 的耐心解答! 真的学到很多 🙏', '2026-05-10 10:12:00.000', '2026-05-10 10:12:00.000', 0, 0),
  ('scmt-005-007', 'sol-s-005', 'scmt-005-001', 'super-vp-002', '**@alice_coder** 提的 `new HashMap<>(nums.length * 2)` 我测了下, 确实快 20%+, 关键是避免 rehash。Java 调优就是这些细节。', '2026-05-10 10:11:00.000', '2026-05-10 10:11:00.000', 0, 0),
  ('scmt-005-008', 'sol-s-005', 'scmt-005-007', 'admin-002', '**@super_vp** 提的「反复回看」我执行了一个月, 真的比刷新题有效, 题感提升明显。', '2026-05-10 10:16:00.000', '2026-05-10 10:16:00.000', 0, 0),
  ('scmt-005-009', 'sol-s-005', 'scmt-005-008', 'user-david-004', '**@frank_lee** 提的工具我马上用起来!', '2026-05-10 10:17:00.000', '2026-05-10 10:17:00.000', 0, 0),
  ('scmt-005-010', 'sol-s-005', 'scmt-005-002', 'user-bob-002', '**@david_chen** 答: 负数不影响, 因为 `target - n` 也是负数, 哈希表查找只看 key 是否存在, 跟正负无关。', '2026-05-10 10:13:00.000', '2026-05-10 10:13:00.000', 0, 0),
  ('scmt-005-011', 'sol-s-005', 'scmt-005-010', 'admin-002', '**@super_vp** 那个「反问」环节我也被问过, 当时答得不好, 现在想想应该反问一下面试官的 follow-up 思路。', '2026-05-10 10:17:00.000', '2026-05-10 10:17:00.000', 0, 0),
  ('scmt-005-012', 'sol-s-005', 'scmt-005-011', 'super-root-001', '**@super_vp** 这次讨论真的刷新了我对 two sum 的认识, 不只是题, 是背后的 pattern 🎓', '2026-05-10 10:19:00.000', '2026-05-10 10:19:00.000', 0, 0),
  ('scmt-005-013', 'sol-s-005', 'scmt-005-002', 'user-carol-003', '**@eva_zhang** 会的, **@eva_zhang** 题解系列我每周都在追, 上次那个「最长回文子串」的中心扩展法也很经典。', '2026-05-10 10:15:00.000', '2026-05-10 10:15:00.000', 0, 0),
  ('scmt-005-014', 'sol-s-005', 'scmt-005-013', 'mod-nina-002', '**@super_root** 那个「算法相通」的洞察很重要, 我之前学「单调栈」时, 突然想起 two sum 的「边遍历边维护」, 触类旁通!', '2026-05-10 10:18:00.000', '2026-05-10 10:18:00.000', 0, 0),
  ('scmt-005-015', 'sol-s-005', 'scmt-005-014', 'super-root-001', '**@admin** 提的 EAFP vs LBYL 我之前也纠结过, 现在的准则是「异常罕见就 try, 异常常见就 if」。', '2026-05-10 10:21:00.000', '2026-05-10 10:21:00.000', 0, 0),
  ('scmt-005-016', 'sol-s-005', 'scmt-005-003', 'user-frank-006', '**@nina_mod** 提的 `new HashMap<>(nums.length * 2)` 我测了下, 确实快 20%+, 关键是避免 rehash。Java 调优就是这些细节。', '2026-05-10 10:19:00.000', '2026-05-10 10:19:00.000', 0, 0),
  ('scmt-005-017', 'sol-s-005', 'scmt-005-016', 'admin', '**@bob_dev** 那个时间窗口的工业实现我之前在 Druid 里见过, 内部就是用 LRU + TTL 哈希表做的。', '2026-05-10 10:23:00.000', '2026-05-10 10:23:00.000', 0, 0),
  ('scmt-005-018', 'sol-s-005', 'scmt-005-003', 'mod-mike-001', '**@admin_two** 不行, **@admin_two** 的解法本质就是「用哈希表换 O(1) 查询」, 不用哈希表就只能双重循环 O(n²) 或排序+双指针 O(n log n)。空间 O(1) + 时间 O(n) 是下界。', '2026-05-10 10:25:00.000', '2026-05-10 10:25:00.000', 0, 0),
  ('scmt-005-019', 'sol-s-005', 'scmt-005-018', 'mod-nina-002', '感谢 **@admin_two** 这么详细的解答, 真的学到很多 🙏', '2026-05-10 10:30:00.000', '2026-05-10 10:30:00.000', 0, 0),
  ('scmt-005-020', 'sol-s-005', 'scmt-005-019', 'user-alice-001', '**@carol_wu** 提的边界 case 我整理了一份 edge case 速查表, 自取。', '2026-05-10 10:32:00.000', '2026-05-10 10:32:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-006-001', 'sol-s-006', NULL, 'user-david-004', '时间复杂度 O(n) 很对, 但实测在 n=10^4 时, 双指针反而比哈希表快, 是因为常数问题吗?', '2026-05-12 14:03:00.000', '2026-05-12 14:03:00.000', 0, 0),
  ('scmt-006-002', 'sol-s-006', NULL, 'mod-mike-001', '性能细节: 在 PyPy 3.9 下跑了 100 万次, 平均 0.7ms, 内存峰值 16MB。**@frank_lee** 的解法稳如老狗 🐕', '2026-05-12 14:08:00.000', '2026-05-12 14:08:00.000', 0, 0),
  ('scmt-006-003', 'sol-s-006', NULL, 'super-root-001', '**@frank_lee** 求一个 follow-up: 如果要求返回 **所有** 满足条件的下标对 (不只第一对), 这个 O(n) 解法怎么改?', '2026-05-12 14:15:00.000', '2026-05-12 14:15:00.000', 0, 0),
  ('scmt-006-004', 'sol-s-006', 'scmt-006-001', 'admin-002', '**@super_vp** 那个「工业界变种」我也遇到过: 写风控系统时, 实时匹配「用户行为 A + 行为 B 同时出现」, 用的就是这题的 pattern。哈希表是核心数据结构。', '2026-05-12 14:08:00.000', '2026-05-12 14:08:00.000', 0, 0),
  ('scmt-006-005', 'sol-s-006', 'scmt-006-004', 'super-vp-002', '**@alice_coder** 完美的回复! 负数场景困扰我很久, 终于搞明白了 🎉', '2026-05-12 14:12:00.000', '2026-05-12 14:12:00.000', 0, 0),
  ('scmt-006-006', 'sol-s-006', 'scmt-006-001', 'super-root-001', '**@admin** 那个「工业界变种」我也遇到过: 写风控系统时, 实时匹配「用户行为 A + 行为 B 同时出现」, 用的就是这题的 pattern。哈希表是核心数据结构。', '2026-05-12 14:12:00.000', '2026-05-12 14:12:00.000', 0, 0),
  ('scmt-006-007', 'sol-s-006', 'scmt-006-006', 'user-eva-005', '**@mike_mod** 的回复每次都这么专业, **@mike_mod** 这种「教科书」题解的评论区就该这么高质量 💯', '2026-05-12 14:16:00.000', '2026-05-12 14:16:00.000', 0, 0),
  ('scmt-006-008', 'sol-s-006', 'scmt-006-007', 'user-carol-003', '**@eva_zhang** 感谢! 我去 GitHub 上找 **@eva_zhang** 的代码学习一下 ✨', '2026-05-12 14:17:00.000', '2026-05-12 14:17:00.000', 0, 0),
  ('scmt-006-009', 'sol-s-006', 'scmt-006-002', 'mod-nina-002', '**@super_root** 介意不介意呢? 开源协议是 MIT 嘛, 注明出处 + 不要商用就 OK。我之前用 **@super_root** 的代码也这样, 大家都这么干。', '2026-05-12 14:15:00.000', '2026-05-12 14:15:00.000', 0, 0),
  ('scmt-006-010', 'sol-s-006', 'scmt-006-009', 'user-eva-005', '**@mike_mod** 那个 `unordered_map` 默认构造的问题, 我之前没注意, 看来 C++ 还是要多读《Effective C++》。', '2026-05-12 14:19:00.000', '2026-05-12 14:19:00.000', 0, 0),
  ('scmt-006-011', 'sol-s-006', 'scmt-006-002', 'admin-002', '**@super_vp** 用 `defaultdict` 在这道题里反而慢, 因为 `defaultdict` 每次访问会调用 `__missing__`, 而普通 `dict` 不会。除非你需要「不存在的 key 自动初始化」, 否则普通 dict 更轻。', '2026-05-12 14:15:00.000', '2026-05-12 14:15:00.000', 0, 0),
  ('scmt-006-012', 'sol-s-006', 'scmt-006-011', 'super-root-001', '**@admin** 提的「反复回看」我执行了一个月, 真的比刷新题有效, 题感提升明显。', '2026-05-12 14:19:00.000', '2026-05-12 14:19:00.000', 0, 0),
  ('scmt-006-013', 'sol-s-006', 'scmt-006-003', 'user-bob-002', '**@david_chen** 同意! 知乎上有个高赞回答, 说「刷题 100 道不如把 10 道刷透」, 深以为然。', '2026-05-12 14:22:00.000', '2026-05-12 14:22:00.000', 0, 0),
  ('scmt-006-014', 'sol-s-006', 'scmt-006-013', 'admin-002', '**@super_vp** 的回复每次都这么专业, **@super_vp** 这种「教科书」题解的评论区就该这么高质量 💯', '2026-05-12 14:27:00.000', '2026-05-12 14:27:00.000', 0, 0),
  ('scmt-006-015', 'sol-s-006', 'scmt-006-014', 'super-root-001', '**@super_vp** 提的边界 case 我整理了一份 edge case 速查表, 自取。', '2026-05-12 14:28:00.000', '2026-05-12 14:28:00.000', 0, 0),
  ('scmt-006-016', 'sol-s-006', 'scmt-006-003', 'user-carol-003', '**@eva_zhang** 不行, **@eva_zhang** 的解法本质就是「用哈希表换 O(1) 查询」, 不用哈希表就只能双重循环 O(n²) 或排序+双指针 O(n log n)。空间 O(1) + 时间 O(n) 是下界。', '2026-05-12 14:23:00.000', '2026-05-12 14:23:00.000', 0, 0),
  ('scmt-006-017', 'sol-s-006', 'scmt-006-016', 'admin', '**@bob_dev** 原来如此, 我之前一直以为 `defaultdict` 更快, 反过来了, 震惊!', '2026-05-12 14:27:00.000', '2026-05-12 14:27:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-007-001', 'sol-s-007', NULL, 'admin', '边界 case 我整理了几个: 空数组 / 单元素 / 重复元素 / 负数 target, 都过了。**@mike_mod** 的解法很稳。', '2026-05-14 11:02:00.000', '2026-05-14 11:02:00.000', 0, 0),
  ('scmt-007-002', 'sol-s-007', NULL, 'user-carol-003', '**@mike_mod** 写得太好, 已经推荐给学弟学妹了。我们学校 ACM 队训练就用这套模板。', '2026-05-14 11:07:00.000', '2026-05-14 11:07:00.000', 0, 0),
  ('scmt-007-003', 'sol-s-007', NULL, 'user-frank-006', '**@mike_mod** 写的 Python 版用了 `dict` 而不是 `collections.defaultdict`, 性能会更好吗? 我之前一直用后者, 求指导。', '2026-05-14 11:17:00.000', '2026-05-14 11:17:00.000', 0, 0),
  ('scmt-007-004', 'sol-s-007', 'scmt-007-001', 'user-alice-001', '**@carol_wu** 那个 `try/except` 模式我也试过, 在大数据量下 `try` 块执行成功时反而比 `if x in m` 慢, 因为 `in` 是 C 实现的, 不会抛异常, 所以走的是 fast path。', '2026-05-14 11:09:00.000', '2026-05-14 11:09:00.000', 0, 0),
  ('scmt-007-005', 'sol-s-007', 'scmt-007-004', 'admin-002', '**@super_vp** 那种博客我也写过, 推荐 Hugo + GitHub Pages, 部署简单, 速度也快。', '2026-05-14 11:12:00.000', '2026-05-14 11:12:00.000', 0, 0),
  ('scmt-007-006', 'sol-s-007', 'scmt-007-005', 'user-eva-005', '**@mike_mod** 是的! 我把这次讨论的精华都整理到博客了, 链接见评论区。', '2026-05-14 11:14:00.000', '2026-05-14 11:14:00.000', 0, 0),
  ('scmt-007-007', 'sol-s-007', 'scmt-007-001', 'user-bob-002', '**@david_chen** 那个 LintCode 56, 我同步练过, 比 LeetCode 1 多了「去重」的约束, 难度略升。建议都刷一遍。', '2026-05-14 11:12:00.000', '2026-05-14 11:12:00.000', 0, 0),
  ('scmt-007-008', 'sol-s-007', 'scmt-007-007', 'user-carol-003', '**@eva_zhang** 那个 `__missing__` 性能问题我之前也测过, 默认 `dict.__missing__` 是 pass, 但 `defaultdict` 重写了, 所以有开销。', '2026-05-14 11:16:00.000', '2026-05-14 11:16:00.000', 0, 0),
  ('scmt-007-009', 'sol-s-007', 'scmt-007-008', 'user-david-004', '**@frank_lee** 提的 EAFP vs LBYL 我之前也纠结过, 现在的准则是「异常罕见就 try, 异常常见就 if」。', '2026-05-14 11:19:00.000', '2026-05-14 11:19:00.000', 0, 0),
  ('scmt-007-010', 'sol-s-007', 'scmt-007-002', 'user-eva-005', '**@mike_mod** 写完博客记得加个 `README.md` 和 `LICENSE`, 顺便开 GitHub Pages, 给自己简历加分。', '2026-05-14 11:14:00.000', '2026-05-14 11:14:00.000', 0, 0),
  ('scmt-007-011', 'sol-s-007', 'scmt-007-010', 'admin', '**@bob_dev** 那个 `__missing__` 性能问题我之前也测过, 默认 `dict.__missing__` 是 pass, 但 `defaultdict` 重写了, 所以有开销。', '2026-05-14 11:18:00.000', '2026-05-14 11:18:00.000', 0, 0),
  ('scmt-007-012', 'sol-s-007', 'scmt-007-011', 'user-david-004', '**@frank_lee** 分享的链接收藏了, 周末细看 🔖', '2026-05-14 11:19:00.000', '2026-05-14 11:19:00.000', 0, 0),
  ('scmt-007-013', 'sol-s-007', 'scmt-007-002', 'user-frank-006', '**@nina_mod** 那个「动态流」的题其实更接近 LRU cache, 可以看 LeetCode 146。思路类似, 只是窗口大小固定。', '2026-05-14 11:14:00.000', '2026-05-14 11:14:00.000', 0, 0),
  ('scmt-007-014', 'sol-s-007', 'scmt-007-013', 'admin', '**@bob_dev** 原来如此, 我之前一直以为 `defaultdict` 更快, 反过来了, 震惊!', '2026-05-14 11:18:00.000', '2026-05-14 11:18:00.000', 0, 0),
  ('scmt-007-015', 'sol-s-007', 'scmt-007-003', 'user-david-004', '**@frank_lee** 那个 follow-up, 改成 `defaultdict(list)` 收集所有下标就行: ⏎  ⏎ ```python ⏎ from collections import defaultdict ⏎  ⏎ def twoSumAll(nums, target): ⏎     pos = defaultdict(list) ⏎     res = [] ⏎     for i, n in enumerate(nums): ⏎         if target - n in pos: ⏎             for j in pos[target - n]: ⏎                 res.append([j, i]) ⏎         pos[n].append(i) ⏎     return res ⏎ ``` ⏎  ⏎ 空间 O(n), 时间 O(n)。', '2026-05-14 11:24:00.000', '2026-05-14 11:24:00.000', 0, 0),
  ('scmt-007-016', 'sol-s-007', 'scmt-007-015', 'user-carol-003', '**@eva_zhang** 提的细节我立刻加到自己的代码里!', '2026-05-14 11:29:00.000', '2026-05-14 11:29:00.000', 0, 0),
  ('scmt-007-017', 'sol-s-007', 'scmt-007-003', 'user-eva-005', '**@mike_mod** 复现是好事, 建议加单元测试! 我自己写 C++ 的时候都用 `gtest`, Python 用 `pytest`, 边界 case 覆盖率上 100%。', '2026-05-14 11:27:00.000', '2026-05-14 11:27:00.000', 0, 0),
  ('scmt-007-018', 'sol-s-007', 'scmt-007-017', 'mod-mike-001', '**@admin_two** 这个 `defaultdict` 的代码我收藏了, 等下就测一下 ✨', '2026-05-14 11:30:00.000', '2026-05-14 11:30:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-008-001', 'sol-s-008', NULL, 'user-eva-005', '**@nina_mod** 在 Reddit 上看到有人说这解法「too simple」, 但 LeetCode 评论区里讨论得最多的还是这版。新人就该学这种。', '2026-05-16 16:01:00.000', '2026-05-16 16:01:00.000', 0, 0),
  ('scmt-008-002', 'sol-s-008', NULL, 'admin-002', '**@nina_mod** 在 Reddit 上看到有人说这解法「too simple」, 但 LeetCode 评论区里讨论得最多的还是这版。新人就该学这种。', '2026-05-16 16:10:00.000', '2026-05-16 16:10:00.000', 0, 0),
  ('scmt-008-003', 'sol-s-008', NULL, 'super-vp-002', '**@nina_mod** 求一个 follow-up: 如果要求返回 **所有** 满足条件的下标对 (不只第一对), 这个 O(n) 解法怎么改?', '2026-05-16 16:15:00.000', '2026-05-16 16:15:00.000', 0, 0),
  ('scmt-008-004', 'sol-s-008', 'scmt-008-001', 'admin-002', '**@super_vp** 这种「动态流」版本, 其实更接近工业场景: 维护一个固定大小的窗口, 老的滑出, 新的滑入。可以看 `collections.OrderedDict` 或 LRU cache。', '2026-05-16 16:08:00.000', '2026-05-16 16:08:00.000', 0, 0),
  ('scmt-008-005', 'sol-s-008', 'scmt-008-004', 'user-eva-005', '**@mike_mod** 提的细节我立刻加到自己的代码里!', '2026-05-16 16:11:00.000', '2026-05-16 16:11:00.000', 0, 0),
  ('scmt-008-006', 'sol-s-008', 'scmt-008-005', 'user-alice-001', '**@carol_wu** 真的, **@carol_wu** 的题解 + **@carol_wu** 的评论 = 算法题双保险!', '2026-05-16 16:12:00.000', '2026-05-16 16:12:00.000', 0, 0),
  ('scmt-008-007', 'sol-s-008', 'scmt-008-001', 'super-root-001', '**@admin** 那个 PyPy benchmark 我也跑了, 结论一致。这种「快」主要来自 PyPy 的 JIT, 不是 Python 本身的。生产建议 CPython + 关键路径用 Cython。', '2026-05-16 16:08:00.000', '2026-05-16 16:08:00.000', 0, 0),
  ('scmt-008-008', 'sol-s-008', 'scmt-008-007', 'user-eva-005', '**@mike_mod** 是的, 「反复刷」比「刷更多题」更有效, 我现在改成一周只刷 5 道, 但每道刷 3 遍。', '2026-05-16 16:13:00.000', '2026-05-16 16:13:00.000', 0, 0),
  ('scmt-008-009', 'sol-s-008', 'scmt-008-002', 'user-alice-001', '**@carol_wu** 那个「动态流」的题其实更接近 LRU cache, 可以看 LeetCode 146。思路类似, 只是窗口大小固定。', '2026-05-16 16:14:00.000', '2026-05-16 16:14:00.000', 0, 0),
  ('scmt-008-010', 'sol-s-008', 'scmt-008-009', 'admin', '感谢 **@bob_dev** 这么详细的解答, 真的学到很多 🙏', '2026-05-16 16:19:00.000', '2026-05-16 16:19:00.000', 0, 0),
  ('scmt-008-011', 'sol-s-008', 'scmt-008-010', 'super-vp-002', '**@alice_coder** 提的边界 case 我整理了一份 edge case 速查表, 自取。', '2026-05-16 16:21:00.000', '2026-05-16 16:21:00.000', 0, 0),
  ('scmt-008-012', 'sol-s-008', 'scmt-008-002', 'user-bob-002', '**@david_chen** 写博客分享是好事! 写完后可以把链接发到「题解分享」频道, 我帮你转发。', '2026-05-16 16:17:00.000', '2026-05-16 16:17:00.000', 0, 0),
  ('scmt-008-013', 'sol-s-008', 'scmt-008-012', 'admin-002', '**@super_vp** 提的 PyPy JIT 解释得清楚, 之前一直以为 PyPy 慢, 看来要重新评估。', '2026-05-16 16:20:00.000', '2026-05-16 16:20:00.000', 0, 0),
  ('scmt-008-014', 'sol-s-008', 'scmt-008-013', 'user-eva-005', '**@mike_mod** 分享的链接收藏了, 周末细看 🔖', '2026-05-16 16:23:00.000', '2026-05-16 16:23:00.000', 0, 0),
  ('scmt-008-015', 'sol-s-008', 'scmt-008-003', 'user-carol-003', '**@eva_zhang** 这种「动态流」版本, 其实更接近工业场景: 维护一个固定大小的窗口, 老的滑出, 新的滑入。可以看 `collections.OrderedDict` 或 LRU cache。', '2026-05-16 16:21:00.000', '2026-05-16 16:21:00.000', 0, 0),
  ('scmt-008-016', 'sol-s-008', 'scmt-008-015', 'user-frank-006', '**@nina_mod** 提的 LeetCode 146 我也刷过, 重点是 `get` 和 `put` 的 O(1) 实现, 双链表 + 哈希表是核心。', '2026-05-16 16:25:00.000', '2026-05-16 16:25:00.000', 0, 0),
  ('scmt-008-017', 'sol-s-008', 'scmt-008-016', 'user-carol-003', '**@eva_zhang** 那种「算法相通」的总结非常到位, 我准备整理一份 pattern 速查表。', '2026-05-16 16:28:00.000', '2026-05-16 16:28:00.000', 0, 0),
  ('scmt-008-018', 'sol-s-008', 'scmt-008-003', 'user-david-004', '**@frank_lee** 提的 `new HashMap<>(nums.length * 2)` 我测了下, 确实快 20%+, 关键是避免 rehash。Java 调优就是这些细节。', '2026-05-16 16:24:00.000', '2026-05-16 16:24:00.000', 0, 0),
  ('scmt-008-019', 'sol-s-008', 'scmt-008-018', 'mod-mike-001', '**@admin_two** 那个时间窗口的工业实现我之前在 Druid 里见过, 内部就是用 LRU + TTL 哈希表做的。', '2026-05-16 16:27:00.000', '2026-05-16 16:27:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-009-001', 'sol-s-009', NULL, 'mod-mike-001', '**@admin_two** 这题解太赞了! 一遍哈希表确实是最优解, 思路清晰, 代码也简洁。我之前一直双重循环, 学到了!', '2026-05-19 13:04:00.000', '2026-05-19 13:04:00.000', 0, 0),
  ('scmt-009-002', 'sol-s-009', NULL, 'super-root-001', '有一处建议: **@admin_two** 在 `seen[n] = i` 之后可以加一行 `assert len(seen) == i + 1` 做调试, 方便排查。', '2026-05-19 13:09:00.000', '2026-05-19 13:09:00.000', 0, 0),
  ('scmt-009-003', 'sol-s-009', NULL, 'user-alice-001', '边界 case 我整理了几个: 空数组 / 单元素 / 重复元素 / 负数 target, 都过了。**@admin_two** 的解法很稳。', '2026-05-19 13:17:00.000', '2026-05-19 13:17:00.000', 0, 0),
  ('scmt-009-004', 'sol-s-009', 'scmt-009-001', 'admin', '**@bob_dev** 会的, **@bob_dev** 题解系列我每周都在追, 上次那个「最长回文子串」的中心扩展法也很经典。', '2026-05-19 13:09:00.000', '2026-05-19 13:09:00.000', 0, 0),
  ('scmt-009-005', 'sol-s-009', 'scmt-009-004', 'mod-mike-001', '**@admin_two** 是的, 「反复刷」比「刷更多题」更有效, 我现在改成一周只刷 5 道, 但每道刷 3 遍。', '2026-05-19 13:14:00.000', '2026-05-19 13:14:00.000', 0, 0),
  ('scmt-009-006', 'sol-s-009', 'scmt-009-005', 'super-vp-002', '+1, **@alice_coder** 这个总结我抄到笔记了 📋', '2026-05-19 13:16:00.000', '2026-05-19 13:16:00.000', 0, 0),
  ('scmt-009-007', 'sol-s-009', 'scmt-009-001', 'user-alice-001', '**@carol_wu** 那个 follow-up 我之前发过, 你可以参考我之前那条评论里的代码, **@carol_wu** 的写法可以扩展。', '2026-05-19 13:12:00.000', '2026-05-19 13:12:00.000', 0, 0),
  ('scmt-009-008', 'sol-s-009', 'scmt-009-007', 'user-eva-005', '**@mike_mod** 同意, **@mike_mod** 的题解适合「反复回看」, 我现在每周都过一遍 📅', '2026-05-19 13:17:00.000', '2026-05-19 13:17:00.000', 0, 0),
  ('scmt-009-009', 'sol-s-009', 'scmt-009-008', 'user-frank-006', '**@nina_mod** 感谢! 我去 GitHub 上找 **@nina_mod** 的代码学习一下 ✨', '2026-05-19 13:18:00.000', '2026-05-19 13:18:00.000', 0, 0),
  ('scmt-009-010', 'sol-s-009', 'scmt-009-002', 'admin', '**@bob_dev** 那个 LintCode 56, 我同步练过, 比 LeetCode 1 多了「去重」的约束, 难度略升。建议都刷一遍。', '2026-05-19 13:16:00.000', '2026-05-19 13:16:00.000', 0, 0),
  ('scmt-009-011', 'sol-s-009', 'scmt-009-010', 'user-bob-002', '**@david_chen** 完美的回复! 负数场景困扰我很久, 终于搞明白了 🎉', '2026-05-19 13:21:00.000', '2026-05-19 13:21:00.000', 0, 0),
  ('scmt-009-012', 'sol-s-009', 'scmt-009-002', 'user-alice-001', '**@carol_wu** 那个 `try/except` 模式我也试过, 在大数据量下 `try` 块执行成功时反而比 `if x in m` 慢, 因为 `in` 是 C 实现的, 不会抛异常, 所以走的是 fast path。', '2026-05-19 13:19:00.000', '2026-05-19 13:19:00.000', 0, 0),
  ('scmt-009-013', 'sol-s-009', 'scmt-009-012', 'user-bob-002', '**@carol_wu** 那个 `try/except` 的 EAFP 哲学我之前也踩过坑, 这下彻底想通了。', '2026-05-19 13:22:00.000', '2026-05-19 13:22:00.000', 0, 0),
  ('scmt-009-014', 'sol-s-009', 'scmt-009-013', 'user-frank-006', '+1, **@nina_mod** 这个总结我抄到笔记了 📋', '2026-05-19 13:23:00.000', '2026-05-19 13:23:00.000', 0, 0),
  ('scmt-009-015', 'sol-s-009', 'scmt-009-003', 'mod-nina-002', '**@super_root** 那个 `assert` 调试思路好, 我学到了! 我一般用 `print`, 看来该升级一下工具链了。', '2026-05-19 13:24:00.000', '2026-05-19 13:24:00.000', 0, 0),
  ('scmt-009-016', 'sol-s-009', 'scmt-009-015', 'user-eva-005', '感谢 **@mike_mod** 这么详细的解答, 真的学到很多 🙏', '2026-05-19 13:28:00.000', '2026-05-19 13:28:00.000', 0, 0),
  ('scmt-009-017', 'sol-s-009', 'scmt-009-016', 'mod-nina-002', '**@super_root** 提的 EAFP vs LBYL 我之前也纠结过, 现在的准则是「异常罕见就 try, 异常常见就 if」。', '2026-05-19 13:29:00.000', '2026-05-19 13:29:00.000', 0, 0),
  ('scmt-009-018', 'sol-s-009', 'scmt-009-003', 'admin-002', '**@super_vp** 同意! 知乎上有个高赞回答, 说「刷题 100 道不如把 10 道刷透」, 深以为然。', '2026-05-19 13:26:00.000', '2026-05-19 13:26:00.000', 0, 0),
  ('scmt-009-019', 'sol-s-009', 'scmt-009-018', 'user-carol-003', '**@eva_zhang** 提的 PyPy JIT 解释得清楚, 之前一直以为 PyPy 慢, 看来要重新评估。', '2026-05-19 13:29:00.000', '2026-05-19 13:29:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-010-001', 'sol-s-010', NULL, 'admin-002', '跟着代码敲了一遍, 加了详细注释, 准备发到自己博客上, 注明参考了 **@super_root** 的题解, 介意吗?', '2026-05-21 10:00:00.000', '2026-05-21 10:00:00.000', 0, 0),
  ('scmt-010-002', 'sol-s-010', NULL, 'admin', '我之前一直用 list.index() 实现, 看了你的题解才明白 list.index() 是 O(n), 难怪大数据量卡死。', '2026-05-21 10:08:00.000', '2026-05-21 10:08:00.000', 0, 0),
  ('scmt-010-003', 'sol-s-010', NULL, 'user-carol-003', '性能细节: 在 PyPy 3.9 下跑了 100 万次, 平均 0.7ms, 内存峰值 16MB。**@super_root** 的解法稳如老狗 🐕', '2026-05-21 10:15:00.000', '2026-05-21 10:15:00.000', 0, 0),
  ('scmt-010-004', 'sol-s-010', 'scmt-010-001', 'user-alice-001', '**@carol_wu** 提的 `new HashMap<>(nums.length * 2)` 我测了下, 确实快 20%+, 关键是避免 rehash。Java 调优就是这些细节。', '2026-05-21 10:06:00.000', '2026-05-21 10:06:00.000', 0, 0),
  ('scmt-010-005', 'sol-s-010', 'scmt-010-004', 'super-root-001', '**@admin** 那个 `__missing__` 的细节, 我之前不知道, 受教了! 看来还是要多读 Python 文档。', '2026-05-21 10:11:00.000', '2026-05-21 10:11:00.000', 0, 0),
  ('scmt-010-006', 'sol-s-010', 'scmt-010-001', 'user-bob-002', '**@david_chen** 那个 LintCode 56, 我同步练过, 比 LeetCode 1 多了「去重」的约束, 难度略升。建议都刷一遍。', '2026-05-21 10:08:00.000', '2026-05-21 10:08:00.000', 0, 0),
  ('scmt-010-007', 'sol-s-010', 'scmt-010-006', 'user-carol-003', '**@david_chen** 那个 LRU 的思路, 我之前刷到过, 没想到和 two sum 是同一个 pattern。算法之间是相通的 📚', '2026-05-21 10:13:00.000', '2026-05-21 10:13:00.000', 0, 0),
  ('scmt-010-008', 'sol-s-010', 'scmt-010-002', 'super-vp-002', '**@alice_coder** 这种「动态流」版本, 其实更接近工业场景: 维护一个固定大小的窗口, 老的滑出, 新的滑入。可以看 `collections.OrderedDict` 或 LRU cache。', '2026-05-21 10:12:00.000', '2026-05-21 10:12:00.000', 0, 0),
  ('scmt-010-009', 'sol-s-010', 'scmt-010-008', 'user-eva-005', '**@mike_mod** 的回复每次都这么专业, **@mike_mod** 这种「教科书」题解的评论区就该这么高质量 💯', '2026-05-21 10:16:00.000', '2026-05-21 10:16:00.000', 0, 0),
  ('scmt-010-010', 'sol-s-010', 'scmt-010-009', 'user-carol-003', '**@eva_zhang** 提的 `defaultdict` 性能问题我之前没注意, 测了一下确实慢 5%, 学习了!', '2026-05-21 10:18:00.000', '2026-05-21 10:18:00.000', 0, 0),
  ('scmt-010-011', 'sol-s-010', 'scmt-010-002', 'user-alice-001', '**@bob_dev** 写完博客记得加个 `README.md` 和 `LICENSE`, 顺便开 GitHub Pages, 给自己简历加分。', '2026-05-21 10:16:00.000', '2026-05-21 10:16:00.000', 0, 0),
  ('scmt-010-012', 'sol-s-010', 'scmt-010-011', 'mod-nina-002', '**@super_root** 这个 `defaultdict` 的代码我收藏了, 等下就测一下 ✨', '2026-05-21 10:20:00.000', '2026-05-21 10:20:00.000', 0, 0),
  ('scmt-010-013', 'sol-s-010', 'scmt-010-012', 'super-vp-002', '**@alice_coder** 真的, **@alice_coder** 的题解 + **@alice_coder** 的评论 = 算法题双保险!', '2026-05-21 10:23:00.000', '2026-05-21 10:23:00.000', 0, 0),
  ('scmt-010-014', 'sol-s-010', 'scmt-010-003', 'admin', '**@bob_dev** 那个「灵魂」问题我也在思考, 我觉得是后者: 「边遍历边维护」是 pattern, 哈希表只是工具。其他很多题 (如「两数之和 II」输入有序) 用的是双指针 pattern。', '2026-05-21 10:22:00.000', '2026-05-21 10:22:00.000', 0, 0),
  ('scmt-010-015', 'sol-s-010', 'scmt-010-014', 'user-bob-002', '**@david_chen** 完美的回复! 负数场景困扰我很久, 终于搞明白了 🎉', '2026-05-21 10:26:00.000', '2026-05-21 10:26:00.000', 0, 0),
  ('scmt-010-016', 'sol-s-010', 'scmt-010-003', 'user-alice-001', '**@carol_wu** 介意不介意呢? 开源协议是 MIT 嘛, 注明出处 + 不要商用就 OK。我之前用 **@carol_wu** 的代码也这样, 大家都这么干。', '2026-05-21 10:25:00.000', '2026-05-21 10:25:00.000', 0, 0),
  ('scmt-010-017', 'sol-s-010', 'scmt-010-016', 'user-eva-005', '**@mike_mod** 那个「反问」环节我也被问过, 当时答得不好, 现在想想应该反问一下面试官的 follow-up 思路。', '2026-05-21 10:30:00.000', '2026-05-21 10:30:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-011-001', 'sol-s-011', NULL, 'admin', '请教一下, **@super_vp** 在 `target - n in seen` 这一步, 如果数组里有负数会出问题吗? 我测了几个 case, 好像不会, 但原理上不太确定。', '2026-05-23 14:04:00.000', '2026-05-23 14:04:00.000', 0, 0),
  ('scmt-011-002', 'sol-s-011', NULL, 'user-carol-003', '我之前一直用 list.index() 实现, 看了你的题解才明白 list.index() 是 O(n), 难怪大数据量卡死。', '2026-05-23 14:08:00.000', '2026-05-23 14:08:00.000', 0, 0),
  ('scmt-011-003', 'sol-s-011', NULL, 'user-frank-006', '**@super_vp** 我注意到你用 `if x in seen` 而不是 `try/except`, 这块有什么考量? 之前看有些人推荐 EAFP 风格。', '2026-05-23 14:18:00.000', '2026-05-23 14:18:00.000', 0, 0),
  ('scmt-011-004', 'sol-s-011', 'scmt-011-001', 'mod-nina-002', '**@super_root** 复现是好事, 建议加单元测试! 我自己写 C++ 的时候都用 `gtest`, Python 用 `pytest`, 边界 case 覆盖率上 100%。', '2026-05-23 14:11:00.000', '2026-05-23 14:11:00.000', 0, 0),
  ('scmt-011-005', 'sol-s-011', 'scmt-011-004', 'user-carol-003', '**@eva_zhang** 那个 `__missing__` 的细节, 我之前不知道, 受教了! 看来还是要多读 Python 文档。', '2026-05-23 14:15:00.000', '2026-05-23 14:15:00.000', 0, 0),
  ('scmt-011-006', 'sol-s-011', 'scmt-011-001', 'admin-002', '**@super_vp** 那个「灵魂」问题我也在思考, 我觉得是后者: 「边遍历边维护」是 pattern, 哈希表只是工具。其他很多题 (如「两数之和 II」输入有序) 用的是双指针 pattern。', '2026-05-23 14:13:00.000', '2026-05-23 14:13:00.000', 0, 0),
  ('scmt-011-007', 'sol-s-011', 'scmt-011-006', 'user-frank-006', '**@nina_mod** 那个 `try/except` 的 fast path 我之前误解了, 「EAFP 比 LBYL 慢」是反过来的, 学习了!', '2026-05-23 14:17:00.000', '2026-05-23 14:17:00.000', 0, 0),
  ('scmt-011-008', 'sol-s-011', 'scmt-011-007', 'mod-mike-001', '**@admin_two** 感谢解答, 真的醍醐灌顶!', '2026-05-23 14:19:00.000', '2026-05-23 14:19:00.000', 0, 0),
  ('scmt-011-009', 'sol-s-011', 'scmt-011-002', 'admin', '**@bob_dev** 那个 LintCode 56, 我同步练过, 比 LeetCode 1 多了「去重」的约束, 难度略升。建议都刷一遍。', '2026-05-23 14:13:00.000', '2026-05-23 14:13:00.000', 0, 0),
  ('scmt-011-010', 'sol-s-011', 'scmt-011-009', 'user-alice-001', '**@bob_dev** 的回复每次都这么专业, **@bob_dev** 这种「教科书」题解的评论区就该这么高质量 💯', '2026-05-23 14:17:00.000', '2026-05-23 14:17:00.000', 0, 0),
  ('scmt-011-011', 'sol-s-011', 'scmt-011-010', 'admin', '**@bob_dev** 同意! 反复回看经典题, 比刷新题效率高 10 倍 📈', '2026-05-23 14:18:00.000', '2026-05-23 14:18:00.000', 0, 0),
  ('scmt-011-012', 'sol-s-011', 'scmt-011-002', 'user-alice-001', '**@carol_wu** 会的, **@carol_wu** 题解系列我每周都在追, 上次那个「最长回文子串」的中心扩展法也很经典。', '2026-05-23 14:18:00.000', '2026-05-23 14:18:00.000', 0, 0),
  ('scmt-011-013', 'sol-s-011', 'scmt-011-012', 'user-eva-005', '**@mike_mod** 知乎那篇我也看过, 作者是个 ACM 退役选手, 写得确实深入。', '2026-05-23 14:21:00.000', '2026-05-23 14:21:00.000', 0, 0),
  ('scmt-011-014', 'sol-s-011', 'scmt-011-003', 'super-vp-002', '**@alice_coder** 那个 `try/except KeyError` 我之前用错场景了, Python EAFP 在「异常罕见」的场景下最优, 这道题里 `target - n` 大概率不在, 所以适合 try。', '2026-05-23 14:22:00.000', '2026-05-23 14:22:00.000', 0, 0),
  ('scmt-011-015', 'sol-s-011', 'scmt-011-014', 'user-alice-001', '**@carol_wu** 那个 LintCode 56 我去练一下, 感谢推荐!', '2026-05-23 14:27:00.000', '2026-05-23 14:27:00.000', 0, 0),
  ('scmt-011-016', 'sol-s-011', 'scmt-011-015', 'user-david-004', '**@frank_lee** 这次讨论值得归档, 谢谢大家! 🙌', '2026-05-23 14:28:00.000', '2026-05-23 14:28:00.000', 0, 0),
  ('scmt-011-017', 'sol-s-011', 'scmt-011-003', 'admin', '**@bob_dev** 那个 PyPy benchmark 我也跑了, 结论一致。这种「快」主要来自 PyPy 的 JIT, 不是 Python 本身的。生产建议 CPython + 关键路径用 Cython。', '2026-05-23 14:26:00.000', '2026-05-23 14:26:00.000', 0, 0),
  ('scmt-011-018', 'sol-s-011', 'scmt-011-017', 'user-alice-001', '**@bob_dev** 那种博客我也写过, 推荐 Hugo + GitHub Pages, 部署简单, 速度也快。', '2026-05-23 14:30:00.000', '2026-05-23 14:30:00.000', 0, 0),
  ('scmt-011-019', 'sol-s-011', 'scmt-011-018', 'mod-nina-002', '**@super_root** 分享的链接收藏了, 周末细看 🔖', '2026-05-23 14:32:00.000', '2026-05-23 14:32:00.000', 0, 0);
INSERT IGNORE INTO `solution_comments` (`id`, `solution_id`, `parent_id`, `user_id`, `content`, `created_at`, `updated_at`, `is_flagged`, `is_deleted`) VALUES
  ('scmt-012-001', 'sol-s-012', NULL, 'super-vp-002', '**@admin** 我注意到你用 `if x in seen` 而不是 `try/except`, 这块有什么考量? 之前看有些人推荐 EAFP 风格。', '2026-05-26 11:01:00.000', '2026-05-26 11:01:00.000', 0, 0),
  ('scmt-012-002', 'sol-s-012', NULL, 'user-bob-002', '**@admin** 求一个空间优化版: 不用哈希表能不能 O(n) 解? 我想了很久, 似乎不行, 但想听听你的思路。', '2026-05-26 11:08:00.000', '2026-05-26 11:08:00.000', 0, 0),
  ('scmt-012-003', 'sol-s-012', NULL, 'user-eva-005', '有一个 follow-up: 如果数组是动态的 (持续流入新元素 + 实时查询 target), 这种解法还成立吗?', '2026-05-26 11:17:00.000', '2026-05-26 11:17:00.000', 0, 0),
  ('scmt-012-004', 'sol-s-012', 'scmt-012-001', 'user-eva-005', '**@mike_mod** 会的, **@mike_mod** 题解系列我每周都在追, 上次那个「最长回文子串」的中心扩展法也很经典。', '2026-05-26 11:07:00.000', '2026-05-26 11:07:00.000', 0, 0),
  ('scmt-012-005', 'sol-s-012', 'scmt-012-004', 'super-root-001', '**@admin** 原来如此, 我之前一直以为 `defaultdict` 更快, 反过来了, 震惊!', '2026-05-26 11:12:00.000', '2026-05-26 11:12:00.000', 0, 0),
  ('scmt-012-006', 'sol-s-012', 'scmt-012-005', 'user-alice-001', '**@carol_wu** 提的 `defaultdict` 性能问题我之前没注意, 测了一下确实慢 5%, 学习了!', '2026-05-26 11:14:00.000', '2026-05-26 11:14:00.000', 0, 0),
  ('scmt-012-007', 'sol-s-012', 'scmt-012-001', 'user-frank-006', '**@nina_mod** 那个 `try/except` 模式我也试过, 在大数据量下 `try` 块执行成功时反而比 `if x in m` 慢, 因为 `in` 是 C 实现的, 不会抛异常, 所以走的是 fast path。', '2026-05-26 11:11:00.000', '2026-05-26 11:11:00.000', 0, 0),
  ('scmt-012-008', 'sol-s-012', 'scmt-012-007', 'super-vp-002', '**@alice_coder** 提的细节我立刻加到自己的代码里!', '2026-05-26 11:16:00.000', '2026-05-26 11:16:00.000', 0, 0),
  ('scmt-012-009', 'sol-s-012', 'scmt-012-008', 'mod-mike-001', '**@admin_two** 真的, **@admin_two** 的题解 + **@admin_two** 的评论 = 算法题双保险!', '2026-05-26 11:18:00.000', '2026-05-26 11:18:00.000', 0, 0),
  ('scmt-012-010', 'sol-s-012', 'scmt-012-002', 'user-frank-006', '**@nina_mod** 那个「工业界变种」我也遇到过: 写风控系统时, 实时匹配「用户行为 A + 行为 B 同时出现」, 用的就是这题的 pattern。哈希表是核心数据结构。', '2026-05-26 11:14:00.000', '2026-05-26 11:14:00.000', 0, 0),
  ('scmt-012-011', 'sol-s-012', 'scmt-012-010', 'admin', '**@bob_dev** 那个 `__missing__` 性能问题我之前也测过, 默认 `dict.__missing__` 是 pass, 但 `defaultdict` 重写了, 所以有开销。', '2026-05-26 11:18:00.000', '2026-05-26 11:18:00.000', 0, 0),
  ('scmt-012-012', 'sol-s-012', 'scmt-012-002', 'mod-mike-001', '**@admin_two** 那个 follow-up, 改成 `defaultdict(list)` 收集所有下标就行: ⏎  ⏎ ```python ⏎ from collections import defaultdict ⏎  ⏎ def twoSumAll(nums, target): ⏎     pos = defaultdict(list) ⏎     res = [] ⏎     for i, n in enumerate(nums): ⏎         if target - n in pos: ⏎             for j in pos[target - n]: ⏎                 res.append([j, i]) ⏎         pos[n].append(i) ⏎     return res ⏎ ``` ⏎  ⏎ 空间 O(n), 时间 O(n)。', '2026-05-26 11:18:00.000', '2026-05-26 11:18:00.000', 0, 0),
  ('scmt-012-013', 'sol-s-012', 'scmt-012-012', 'super-vp-002', '**@alice_coder** 那个时间窗口的工业实现我之前在 Druid 里见过, 内部就是用 LRU + TTL 哈希表做的。', '2026-05-26 11:21:00.000', '2026-05-26 11:21:00.000', 0, 0),
  ('scmt-012-014', 'sol-s-012', 'scmt-012-013', 'user-frank-006', '**@nina_mod** 提的边界 case 我整理了一份 edge case 速查表, 自取。', '2026-05-26 11:23:00.000', '2026-05-26 11:23:00.000', 0, 0),
  ('scmt-012-015', 'sol-s-012', 'scmt-012-003', 'user-carol-003', '**@eva_zhang** 那个 follow-up, 改成 `defaultdict(list)` 收集所有下标就行: ⏎  ⏎ ```python ⏎ from collections import defaultdict ⏎  ⏎ def twoSumAll(nums, target): ⏎     pos = defaultdict(list) ⏎     res = [] ⏎     for i, n in enumerate(nums): ⏎         if target - n in pos: ⏎             for j in pos[target - n]: ⏎                 res.append([j, i]) ⏎         pos[n].append(i) ⏎     return res ⏎ ``` ⏎  ⏎ 空间 O(n), 时间 O(n)。', '2026-05-26 11:24:00.000', '2026-05-26 11:24:00.000', 0, 0),
  ('scmt-012-016', 'sol-s-012', 'scmt-012-015', 'user-bob-002', '**@david_chen** 那个 `try/except` 的 EAFP 哲学我之前也踩过坑, 这下彻底想通了。', '2026-05-26 11:29:00.000', '2026-05-26 11:29:00.000', 0, 0),
  ('scmt-012-017', 'sol-s-012', 'scmt-012-016', 'mod-mike-001', '**@admin_two** 提的 `__missing__` 细节, 我之前没注意, 看来要重读 Python data model。', '2026-05-26 11:31:00.000', '2026-05-26 11:31:00.000', 0, 0),
  ('scmt-012-018', 'sol-s-012', 'scmt-012-003', 'user-david-004', '**@frank_lee** 动态流场景, 我在 Kafka Streams 里见过类似实现, 维护一个时间窗口, 窗口内的元素做匹配, 窗口外的淘汰。本质就是带 TTL 的哈希表。', '2026-05-26 11:27:00.000', '2026-05-26 11:27:00.000', 0, 0),
  ('scmt-012-019', 'sol-s-012', 'scmt-012-018', 'admin', '**@bob_dev** 是的, 「反复刷」比「刷更多题」更有效, 我现在改成一周只刷 5 道, 但每道刷 3 遍。', '2026-05-26 11:31:00.000', '2026-05-26 11:31:00.000', 0, 0),
  ('scmt-012-020', 'sol-s-012', 'scmt-012-019', 'mod-mike-001', '**@admin_two** 太赞了! 直接 mark!', '2026-05-26 11:32:00.000', '2026-05-26 11:32:00.000', 0, 0);
